window.TXB=window.TXB||{};TXB["alab/Deu"]={"1:1":"هذه هي الأقوال التي خاطب بها موسى جميع الإسرائيليين المخيمين في وادي العربة، في صحراء موآب شرقي نهر الأردن، مقابل سوف، ما بين فاران وتوفل ولابان وحضيروت وذي ذهب.","1:2":"وكانت الرحلة تستغرق من حوريب عبر طريق جبل سعير إلى قادش برنيع أحد عشر يوما.","1:3":"ففي اليوم الأول من الشهر الحادي عشر (أي شباط - فبراير)، في السنة الأربعين، خاطب موسى بني إسرائيل بكل ما أوصاه به الرب إليهم،","1:4":"وذلك بعد هزيمة سيحون ملك الأموريين المقيم في حشبون، وعوج ملك باشان الساكن في عشتاروث في إذرعي.","1:5":"وابتدأ موسى في أرض موآب شرقي نهر الأردن يشرح الشريعة قائلا:","1:6":"«لقد قال الرب إلهنا لنا في جبل حوريب: كفاكم المقام في هذا الجبل.","1:7":"تحولوا وتقدموا وادخلوا جبل الأموريين وكل ما يليه من وادي العربة والجبل والسهل والنقب وساحل بحر أرض الكنعانيين ولبنان، إلى النهر الكبير نهر الفرات.","1:8":"وانظروا، فها أنا قد وهبتكم الأرض، فادخلوا وتملكوها لأني أقسمت أن أعطيها لآبائكم إبراهيم وإسحق ويعقوب ولنسلهم من بعدهم».","1:9":"وقال موسى للشعب: «لا أقدر وحدي أن أتحمل مسئوليتكم،","1:10":"فقد كثركم الرب إلهكم، وها أنتم قد أصبحتم اليوم في كثرة نجوم السماء.","1:11":"فليزدكم الرب إله آبائكم ألف مرة ويبارككم كما وعدكم.","1:12":"ولكن كيف يمكن أن أحمل وحدي مشاكلكم وأثقالكم وخصوماتكم؟","1:13":"فاختاروا من أسباطكم رجالا حكماء عقلاء من ذوي المقام، فأجعلهم قادة لكم.","1:14":"فأجبتموني قائلين: إن ما تقترح علينا أن نفعله أمر صائب.","1:15":"فاخترت رؤساء أسباطكم رجالا حكماء من ذوي المقام، وأقمتهم قادة عليكم، فكانوا رؤساء ألوف ومئات وخماسين وعشرات، وعرفاء لأسباطكم.","1:16":"وأمرت قضاتكم آنئذ قائلا: استمعوا إلى الخصومات الناشبة بين إخوتكم واقضوا بالعدل بين الإسرائيلي وأخيه أو بين الإسرائيلي والنزيل.","1:17":"لا تحابوا في القضاء واستمعوا للصغير كما تستمعون للكبير. لا تهابوا إنسانا، لأن القضاء لله. وما يشكل عليكم من أمر ترفعونه إلي فأقضي فيه.","1:18":"وأوصيتكم في ذلك الوقت بجميع الأمور التي يجب أن تجروها.","1:19":"ثم ارتحلنا بموجب أمر الرب من جبل حوريب مجتازين تلك الصحراء العظيمة المخوفة التي رأيتموها، متجهين نحو بلاد الأموريين الجبلية، إلى أن أقبلنا على قادش برنيع.","1:20":"فقلت لكم: ها قد جئتم إلى بلاد الأموريين الجبلية التي وهبها لنا الرب إلهنا،","1:21":"فانظروا لأن الرب إلهكم قد أعطاكم الأرض، فاصعدوا واستولوا عليها كما وعد الرب إله آبائكم. لا تخافوا ولا ترتعبوا.","1:22":"فتقدمتم إلي جميعكم وقلتم: دعنا نرسل قوما ليتجسسوا الأرض لنا، ثم يوافونا بنبإ الطريق التي نسلكها والمدن التي نجتاز بها.","1:23":"فراقني الاقتراح، وانتخبت منكم اثني عشر رجلا، واحدا من كل سبط.","1:24":"فاخترقوا مسالك الجبال حتى وصلوا وادي أشكول، فاستكشفوه،","1:25":"وقطفوا من ثمار الأرض وحملوها إلينا، وقالوا: الأرض التي وهبها لنا الرب إلهنا أرض جيدة.","1:26":"لكنكم تقاعستم عن الصعود إليها وعصيتم أمر الرب إلهكم،","1:27":"وتذمرتم في خيامكم قائلين: لأن الرب يكرهنا أخرجنا من أرض مصر ليوقعنا في أيدي الأموريين ويهلكنا.","1:28":"فإلى أين نذهب؟ لقد أوهن إخوتنا قلوبنا عندما أخبرونا أن أهل الأرض أعظم منا وأكثر طولا، ومدنهم عظيمة تبلغ حصونها عنان السماء، وقد شاهدنا هناك بني عناق أيضا.","1:29":"فقلت لكم: لا تجزعوا ولا تخافوا منهم،","1:30":"لأن الرب إلهكم السائر أمامكم هو يحارب عنكم كما رأيتموه معكم في مصر.","1:31":"كذلك شهدتم في الصحراء كيف حملكم الرب إلهكم كما يحمل الإنسان ابنه، في كل الطريق التي سلكتموها، حتى أقبلتم إلى هذا المكان.","1:32":"ولكن على الرغم من ذلك فإنكم لم تثقوا بالرب إلهكم","1:33":"السائر أمامكم في رحلتكم، ليلتمس لكم مكانا تنزلون فيه. فكان يقودكم في عمود نار ليلا وفي عمود سحاب نهارا.","1:34":"وسمع الرب تذمركم فسخط عليكم وأقسم قائلا:","1:35":"لن يرى إنسان من هذا الجيل الشرير الأرض الجيدة التي أقسمت أن أهبها لآبائكم.","1:36":"إلا كالب بن يفنة، فهو يراها وأورثه هو وبنيه الأرض التي وطئها، لأنه أطاع الرب من كل قلبه.","1:37":"كما غضب الرب على بسببكم قائلا: وأنت أيضا لن تدخل الأرض.","1:38":"إنما يشوع بن نون الماثل أمامك هو يدخلها فشجعه لأنه هو الذي يوزعها على الإسرائيليين.","1:39":"أما أطفالكم الذين ادعيتم أنهم يصبحون غنيمة، وصغاركم الذين لا يميزون بعد الخير والشر، فهم يدخلون إلى هناك ولهم أهب الأرض وهم يرثونها.","1:40":"وأما أنتم فتحولوا وارتحِلوا إلى الصحراء على محاذاة طريق البحر الأحمر.","1:41":"فأجبتم وقلتم لي: لقد أخطأنا إلى الرب، ونحن صاعدون إلى الحرب حسب كل ما أمرنا به الرب إلهنا. وحمل كل واحد سلاحه، مستخفا بمصاعب ارتقاء الجبال.","1:42":"فأمرني الرب: قل لهم لا تصعدوا ولا تحاربوا، لأني لست في وسطكم، لئلا تنهزموا أمام أعدائكم.","1:43":"فكلمتكم ولكنكم لم تسمعوا، بل عصيتم أمر الرب وتمردتم وصعدتم إلى الأراضي الجبلية.","1:44":"فاندفع الأموريون المستوطنون في الأراضي الجبلية للقائكم، وطاردوكم كما يطارد النحل، وهزموكم في سعير حتى تخوم حرمة.","1:45":"فرجعتم ونحتم أمام الرب، ولم يسمع الرب لصوتكم ولا أنصت إليكم.","1:46":"ومكثتم في قادش أياما كثيرة، أي طوال الفترة التي بقيتم فيها هناك.","2:1":"ثم تحولنا وانطلقنا نحو الصحراء في اتجاه البحر الأحمر كما أمرني الرب، ودرنا حول جبل سعير أياما كثيرة.","2:2":"ثم قال الرب لي:","2:3":"حسبكم دوران حول هذا الجبل. هيا اتجهوا نحو الشمال.","2:4":"وأوص الشعب: ها أنتم عابرون بتخوم إخوتكم بني عيسو المستوطنين في سعير فيعتريهم الخوف منكم","2:5":"فاحذروا جدا أن تهاجموهم، لأنني لا أورثكم من أرضهم ولا وطأة قدم، لأني قد أعطيت جبل سعير ميراثا لعيسو.","2:6":"تدفعون ثمن ما تشترونه من طعام لتأكلوا، وما تبتاعونه من ماء لتشربوا.","2:7":"لأن الرب إلهكم بارك كل عمل أيديكم، واعتنى بكم في أثناء رحلتكم في هذه الصحراء الشاسعة، وكان معكم طوال أربعين سنة، فلم يعوزكم شيء","2:8":"فاجتزنا بإخوتنا بني عيسو المقيمين في سعير، متجهين في طريق وادي العربة جنوبا صوب إيلات وعصيون جابر، ثم انثنينا ومررنا في طريق صحراء موآب.","2:9":"فقال لي الرب: لا تعاد الموآبيين ولا تثر عليهم حربا، لأني لا أعطيك من أرضهم ميراثا، إذ وهبت عار لذرية لوط ملكا.","2:10":"فقد سكن فيها الإيميون قبلا، وهم شعب كثير وطوال القامة كالعناقيين،","2:11":"وهم يعتبرون رفائيين كالعناقيين. غير أن الموآبيين يدعونهم الإيميين.","2:12":"كذلك استوطن الحوريون أرض سعير من قبل، فطردهم بنو عيسو وأبادوهم وحلوا مكانهم، تماما كما فعل الإسرائيليون بالأرض التي وهبها لهم الرب.","2:13":"والآن انهضوا واعبروا وادي زارد. وهكذا عبرنا وادي زارد.","2:14":"وكان عدد السنوات التي قضيناها في مسيرنا من قادش برنيع حتى اجتزنا وادي زارد ثماني وثلاثين سنة، فيها مات جيل رجال الحرب من المخيم، كما أقسم الرب لهم.","2:15":"وهكذا عاقبهم الرب أيضا حتى أبادهم وأفناهم من المخيم.","2:16":"فعندما مات جميع المقاتلين من بين الشعب","2:17":"قال الرب لي:","2:18":"أنت عابر اليوم بحدود عار من أرض موآب،","2:19":"فمتى اقتربت من بني عمون، لا تعادهم ولا تهاجمهم، لأني لا أهبك من أرض بني عمون ميراثا، إذ وهبتها لبني لوط.","2:20":"وهي أيضا تعتبر أرض رفائيين، إذ سكنوا فيها قبلا. أما العمونيون فيدعونهم زمزميين.","2:21":"وهم شعب كثير طوال القامة كالعناقيين، أبادهم الرب من أمام العمونيين فطردوهم وأقاموا مكانهم،","2:22":"تماما كما فعل لذرية عيسو المستوطنين في سعير. فقد أهلك الحوريين في أيامهم، فطردوهم وحلوا مكانهم إلى هذا اليوم.","2:23":"وكذلك أباد الكفتوريون الذين خرجوا من كفتور، العويين الذين كانوا قاطنين في القرى المنتشرة حتى غزة وحلوا مكانهم.","2:24":"فقوموا وارتحلوا واعبروا وادي نهر أرنون، وانظروا لأنني قد نصرتك على سيحون ملك الأموريين وأرضه. فابتديء بتملك الأرض، وأثر عليه حربا.","2:25":"ففي هذا اليوم بالذات أجعل هيبتكم والخوف منكم يطغيان على شعوب الأرض. وكل الذين يسمعون أخباركم يرتعدون ويفزعون أمامكم.","2:26":"فأرسلت رسلا من صحراء قديموت إلى سيحون ملك حشبون، أعرض عليه سلاما قائلا:","2:27":"دعني أجتز بأرضك سالكا الطريق العامة، لا أحيد عنها يمينا أو شمالا.","2:28":"وسأدفع ثمن ما تبيعني من طعام لآكل، وما تعطيني من ماء لأشرب، أمر راجلا فقط.","2:29":"كما فعلت مع بني عيسو المستوطنين في سعير، والموآبيين المقيمين في عار.","2:30":"لكن سيحون ملك حشبون رفض أن يدعنا نجتاز ببلاده، لأن الرب إلهكم قسى روحه وأغلظ قلبه لكي يهزمه على أيديكم كما فعل الآن.","2:31":"وقال لي الرب: انظر، ها قد ابتدأت أدفع أمامك سيحون لتستولي على أرضه، فأسرع في تملكها حتى تتغلب عليها كلها.","2:32":"فخرج سيحون بكامل جيشه إلى ياهص لمحاربتنا.","2:33":"فأتانا النصر عليه من عند الرب إلهنا، فدحرناه وأبناءه وسائر جيشه.","2:34":"واستولينا على جميع مدنه، وقضينا في كل مدينة على الرجال والنساء والأطفال، فلم ينج حي منهم.","2:35":"ولكن البهائم والأسلاب التي نهبناها من المدن أخذناها غنائم لأنفسنا.","2:36":"ولم تمتنع علينا قرية ابتداء من عروعير الواقعة على حافة وادي أرنون والمدينة القائمة فيه، إلى جلعاد، إذ حقق الرب إلهنا لنا النصر على جميعها.","2:37":"ولكننا لم نقترب من أرض العمونيين، ولا ناحية وادي نهر يبوق، ولا المدن الجبلية طاعة لأمر الرب إلهنا.","3:1":"ثم تحولنا واتجهنا نحو طريق باشان، فخرج عوج ملك باشان لمحاربتنا بكامل جيشه، في إذرعي.","3:2":"فقال لي الرب: «لا تخف منه. قد نصرتك عليه مع سائر جيشه وأرضه، فتفعل به كما فعلت بسيحون ملك الأموريين الذي كان مقيما في حشبون.","3:3":"فحقق لنا إلهنا النصر أيضا على عوج ملك باشان وعلى سائر جيشه، فهزمناه حتى لم ينج منهم حي،","3:4":"واستولينا على جميع مدنه وكل قراه. فكانت في جملتها ستين مدينة منتشرة في كل منطقة أرجوب التي تشكل مملكة عوج في باشان.","3:5":"وكانت جميع هذه مدنا محصنة بالأسوار العالية والأبواب والمزاليج، فضلا عن قرى الصحراء الكثيرة.","3:6":"فدمرناها كما فعلنا بمدن سيحون ملك حشبون، وقضينا على الرجال والنساء والأطفال.","3:7":"ولكننا غنمنا لأنفسنا كل البهائم وأسلاب المدن.","3:8":"وأخذنا حينئذ من أيدي ملكي الأموريين الأرض الواقعة شرقي نهر الأردن من وادي أرنون حتى جبل حرمون.","3:9":"ويدعو الصيدونيون جبل حرمون «سريون». أما الأموريون فيدعونه «سنير».","3:10":"وهكذا استولينا على جميع مدن السهل وسائر جلعاد وباشان إلى سلخة وإذرعي مدينتي مملكة عوج في باشان.","3:11":"وكان عوج آخر الجبابرة الرفائيين. وكان سريره مصنوعا من حديد، ولا يزال محفوظا في (متحف) ربة بني عمون. طوله تسع أذرع (نحو أربعة أمتار ونصف المتر) وعرضه أربع أذرع (نحو مترين).","3:12":"وقد امتلكنا آنئذ هذه الأرض، فأعطيت للرأوبينيين والجاديين بلاد عروعير الواقعة على وادي أرنون ونصف جبل جلعاد.","3:13":"كما أعطيت لنصف سبط منسى بقية جلعاد، وكل منطقة أرجوب وباشان التي كانت تشكل مملكة عوج، وهي تدعى أيضا أرض الرفائيين.","3:14":"فأخذ يائير من ذرية منسى جميع منطقة أرجوب حتى حدود الجشوريين والمعكيين، وأطلق اسمه على أرض باشان، فدعاها حووث يائير (ومعناها قرى يائير) إلى هذا اليوم.","3:15":"كذلك أعطيت ماكير جلعاد.","3:16":"أما الرأوبينيون والجاديون فقد ملكتهم المنطقة الممتدة من جلعاد حتى منتصف وادي أرنون، حيث تنتهي حدودهم. وكذلك إلى وادي يبوق المتاخم لحدود بني عمون.","3:17":"كما امتدت حدودهم إلى الغرب حتى نهر الأردن في وادي العربة، من كنارة إلى البحر الميت تحت سفوح جبل الفسجة شرقا.","3:18":"وأمرت سبطي رأوبين وجاد ونصف سبط منسى قائلا: قد أورثكم الرب إلهكم هذه الأرض لتمتلكوها. فليعبر أبطالكم مدججين بالسلاح في طليعة إخوتكم بني إسرائيل.","3:19":"ولتمكث نساؤكم وأطفالكم ومواشيكم، التي أعلم كثرتها، في مدنكم التي وهبتها لكم","3:20":"إلى أن يمتلك إخوتكم الأرض التي يورثها الرب إلهكم لهم غربي الأردن ويريحهم مثلكم. ثم يرجع كل منكم إلى ملكه الذي وهبته له.","3:21":"وقلت حينذاك ليشوع: لقد شهدت عيناك ما أنزل الرب إلهكم بهذين الملكين، فإنه هكذا سيصنع بجميع الممالك التي أنت عابر إليها.","3:22":"لا تجزعوا منهم لأن الرب إلهكم يحارب عنكم.","3:23":"وتضرعت إلى الرب في ذلك الحين قائلا:","3:24":"ياسيد ها أنت قد ابتدأت تعلن لعبدك عظمتك وقوة قدرتك فأي إله في السماء وعلى الأرض يجري مثل أعمالك وجبروتك.","3:25":"دعني أعبر لأرى لبنان والأرض الخصيبة غربي الأردن بتلالها الطيبة.","3:26":"لكن الرب غضب علي من أجلكم، ولم يستجب لي، بل قال: كفاك. لا تعد تكلمني في هذا الأمر.","3:27":"اصعد إلى قمة جبل الفسجة وتلفت إلى الغرب والشمال والجنوب والشرق وشاهد الأرض بعينيك لكن لن تعبر إلى غربي نهر الأردن.","3:28":"إنما يشوع هو الذي يقود هذا الشعب، وهو الذي يقسم لهم الأرض التي تشاهدها. كذلك أوصه وثبته وشجعه.","3:29":"وهكذا مكثنا في الوادي مقابل بيت فغور.","4:1":"والآن أصغوا يابني إسرائيل إلى الشرائع والأحكام التي أعلمها لكم لتعملوا بها، فتحيوا وتدخلوا لامتلاك الأرض التي يورثها لكم الرب إلهكم","4:2":"لا تضيفوا على ما أوصيكم به ولا تنقصوا منه، بل أطيعوا أوامر الرب إلهكم التي أوصيكم بها.","4:3":"لقد شهدت أعينكم ما أنزل الرب ببعل فغور، إذ أباد الرب إلهكم من بينكم كل من غوى وراء بعل فغور.","4:4":"وأما أنتم الذين تعلقتم بالرب إلهكم فجميعكم أحياء اليوم.","4:5":"انظروا، ها أنا قد علمتكم شرائع وأحكاما كما أمرني الرب إلهي لتعملوا بموجبها في الأرض التي أنتم ماضون إليها لترثوها.","4:6":"فاحفظوها وطبقوها، لأنها هي حكمتكم وفطنتكم لدى الشعوب الذين يسمعون عن هذه الشرائع، فيقولون: إن هذا الشعب العظيم هو حقا شعب حكيم فطن.","4:7":"لأنه أي شعب، مهما عظم، له آلهة قريبة منه مثل الرب إلهنا في كل ما ندعوه؟","4:8":"وأي شعب، مهما عظم، لديه شرائع وأحكام عادلة نظير هذه الشرائع التي أضعها اليوم أمامكم؟","4:9":"إنما احترزوا واحذروا لئلا تنسوا الأمور التي شهدتها أعينكم فلا تنمحي من قلوبكم كل أيام حياتكم. وعلموها لأولادكم ولأحفادكم.","4:10":"ففي اليوم الذي مثلتم فيه أمام الرب إلهكم في جبل حوريب، حين قال لي الرب: اجمع لي الشعب حتى أسمعهم كلامي، فيتعلموا مخافتي طوال أيام حياتهم على الأرض، ويعلموا أولادهم أيضا.","4:11":"فتقدمتم ووقفتم عند سفح الجبل المشتعل بنار امتدت ألسنة لهبها إلى كبد السماء، وتلفعت بسحب داكنة وضباب.","4:12":"فخاطبكم الرب من وسط النار، فسمعتم صوت كلماته من غير أن تبصروا له صورة.","4:13":"وأعلن لكم عهده، الوصايا العشر التي نقشها على لوحي حجر، وأمركم أن تعملوا بها.","4:14":"كما أمرني في ذلك اليوم أن أعلمكم شرائعه وأحكامه لتطبقوها في الأرض التي أنتم ماضون إليها لترثوها.","4:15":"فاحذروا لأنفسكم جدا، فأنتم لم تروا صورة ما حين خاطبكم الرب في جبل حوريب من وسط النار.","4:16":"لئلا تفسدوا فتنحتوا لكم تمثالا لصورة ما لمثال رجل أو امرأة.","4:17":"أو شبه بهيمة ما مما على الأرض، أو شبه طير ما من طيور السماء.","4:18":"أو شبه كائن ما من زواحف الأرض، أو شبه سمك ما مما في الماء تحت الأرض.","4:19":"أو لئلا تتطلعوا إلى السماء فتشاهدوا الشمس والقمر والنجوم والأجرام السماوية التي وزعها الرب إلهكم على جميع الأمم التي تحت السماء، فتغووا وتسجدوا لها وتعبدوها.","4:20":"أما أنتم فقد اختاركم الرب وأخرجكم من أتون الحديد من ديار مصر لتكونوا له شعب ميراثه، كما أنتم اليوم.","4:21":"ولكن الرب غضب علي من أجلكم وأقسم ألا أعبر نهر الأردن ولا أطأ الأرض الخصيبة التي وهبكم إياها الرب إلهكم نصيبا.","4:22":"كذلك فأنا أموت في هذه الأرض من غير أن أجتاز نهر الأردن. وأما أنتم فتعبرونه وترثون تلك الأرض الخصيبة.","4:23":"ولكن إياكم أن تنسوا عهد الرب إلهكم الذي قطعه معكم وتنحتوا لأنفسكم تمثالا لصورة ما مما نهاكم الرب إلهكم عنه.","4:24":"لأن الرب إلهكم هو نار آكلة وإله غيور.","4:25":"وإذا أنجبتم بنين وأحفادا ومكثتم طويلا في الأرض، ثم غويتم فنحتم لكم تمثالا لصورة شيء ما، وارتكبتم الشر في عيني الرب إلهكم لإثارة غيظه،","4:26":"فإنني أشهد عليكم اليوم السماء والأرض، أنكم تنقرضون سريعا من الأرض التي أنتم عابرون نهر الأردن إليها لترثوها، ولن تطول بكم الأيام عليها، إذ لابد أنكم حينئذ هالكون.","4:27":"ويشتتكم الرب بين الأمم فتصبحون أقلية بين الشعوب التي يسوقكم إليها.","4:28":"وهناك تعبدون آلهة من خشب وحجر من صنعة أيدي الناس، مما لا يبصر ولا يسمع ولا يأكل ولا يشم.","4:29":"ولكن إن طلبتم من هناك الرب إلهكم، ملتمسينه من كل قلوبكم ونفوسكم، فإنكم تجدونه.","4:30":"فعندما يكتنفكم الضيق وتصيبكم في آخر الأيام جميع هذه الأمور، عندئذ ترجعون إلى الرب إلهكم وتطيعون أوامره.","4:31":"لأن الرب إلهكم إله رحيم لا ينبذكم ولا يفنيكم، ولا ينسى عهد آبائكم الذي أقسم لهم عليه.","4:32":"فاسألوا عن الأيام الغابرة التي انقضت قبلكم، منذ اليوم الذي خلق الله فيه الإنسان على الأرض. اسأل من أقصى السموات إلى أقصاها: هل حدث قط مثل هذا الأمر العظيم؟ وهل سمع أحد بمثله؟","4:33":"هل سمعت أمة صوت الله يتكلم من وسط النار كما سمعتم أنتم، وعاشت؟","4:34":"وهل حاول إله قط أن يأخذ لنفسه شعبا من وسط شعب آخر مجريا تجارب وآيات ومعجزات وحروبا وقدرة فائقة وقوة شديدة ومخاوف عظيمة كما صنع معكم الرب إلهكم في مصر على مرأى منكم؟","4:35":"لقد اطلعتم على هذه كلها لتعلموا أن الرب هو الإله، وليس آخر سواه.","4:36":"فقد أسمعكم صوته من السماء لينذركم. وأراكم ناره العظيمة على الأرض، وسمعتم صوته من وسط النار.","4:37":"ولأنه قد أحب آباءكم، واختار ذريتهم من بعدهم، أخرجكم بنفسه وبقدرته العظيمة من ديار مصر،","4:38":"وطرد من أمامكم أمما أكبر منكم وأعظم، ليأتي بكم إلى أرضهم ويورثكم إياها، كما حدث في هذا اليوم.","4:39":"فاعترفوا اليوم ورددوا في قلوبكم قائلين: إن الرب هو الإله في السماء من فوق، وعلى الأرض من تحت وليس إله سواه.","4:40":"فاحفظوا اليوم ما أوصيكم به من شرائعه وأحكامه ليحسن الرب إليكم وإلى أولادكم من بعدكم، فيطيل أيامكم على الأرض التي وهبكم إياها إلى الأبد».","4:41":"ثم خصص موسى ثلاث مدن شرقي نهر الأردن،","4:42":"ليلجأ إليها القاتل غير المتعمد، الذي لا يضمر عداء سابقا للقتيل، فيجد في إحدى تلك المدن ملجأ ويحيا.","4:43":"أما هذه المدن فكانت: باصر في الصحراء في أرض السهل في ديار الرأوبينيين وراموت في جلعاد في بلاد الجاديين، وجولان في باشان في منطقة المنسيين.","4:44":"وهذه هي الشريعة التي وضعها أمام بني إسرائيل،","4:45":"وهذه هي الشروط والفرائض والأحكام التي خاطب بها موسى بني إسرائيل عند خروجهم من مصر،","4:46":"وهم مخيمون شرقي نهر الأردن، في الوادي بجوار بيت فغور في أرض سيحون ملك الأموريين الذي كان مقيما في حشبون، فقضى عليه موسى والإسرائيليون عند خروجهم من أرض مصر.","4:47":"فامتلكوا بلاده وبلاد عوج ملك باشان، ملكي الأموريين اللذين كانا مقيمين شرقي نهر الأردن،","4:48":"من عروعير الواقعة على حافة وادي أرنون، إلى جبل سيئون الذي هو حرمون،","4:49":"وكل وادي العربة شرقي نهر الأردن، حتى البحر الميت عند سفوح الفسجة.","5:1":"واستدعى موسى جميع الإسرائيليين وقال لهم: «اسمعوا يابني إسرائيل الشرائع والأحكام التي أتلوها عليكم في هذا اليوم، وتعلموها واحرصوا على ممارستها.","5:2":"قطع الرب إلهنا معنا عهدا في جبل حوريب.","5:3":"ليس مع آبائنا قطع هذا العهد، إنما معنا نحن الذين هنا اليوم جميعا أحياء،","5:4":"إذ تكلم الرب معنا في الجبل من وسط النار وجها لوجه.","5:5":"وكنت أنا واقفا بين الرب وبينكم، لأنكم خفتم من النار، فلم تصعدوا إلى الجبل. فقال الرب:","5:6":"أنا هو الرب إلهك الذي حررك من سجن العبودية في ديار مصر.","5:7":"لا يكن لك آلهة أخرى أمامي.","5:8":"لا تنحت لك تمثالا، ولا صورة ما مما في السماء وما في الأرض وما في الماء تحت الأرض.","5:9":"لا تسجد لها ولا تعبدها، لأني أنا الرب إلهك إله غيور، أفتقد معاصي الآباء في الأبناء حتى الجيل الثالث والرابع من مبغضي.","5:10":"وأحسن إلى ألوف من محبي وطائعي وصاياي.","5:11":"لا تنطق باسم الرب إلهك باطلا، لأن الرب لا يبريء من ينطق باسمه باطلا.","5:12":"احفظ يوم السبت مقدسا كما أوصاك الرب إلهك.","5:13":"ستة أيام تشتغل وتقوم بجميع أعمالك،","5:14":"وأما اليوم السابع فيكون يوم راحة للرب إلهك، لا تقوم فيه بأي عمل أنت وابنك وابنتك وعبدك وأمتك وثورك وحمارك وكل بهائمك، والأجنبي المقيم داخل أبوابك، ليستريح عبدك وأمتك مثلك.","5:15":"وتذكر أنك كنت عبدا في ديار مصر، فأطلقك الرب من هناك بقدرة فائقة وقوة شديدة، لهذا أوصاك الرب إلهك أن ترتاح في يوم السبت.","5:16":"أكرم أباك وأمك كما أمرك الرب إلهك، فتطول أيامك ويكون لك خير على الأرض التي يورثها لك الرب إلهك.","5:17":"لا تقتل.","5:18":"لا تزن.","5:19":"لا تسرق.","5:20":"لا تشهد على جارك شهادة زور.","5:21":"لا تشته امرأة غيرك ولا بيته ولا حقله ولا عبده ولا أمته ولا ثوره ولا حماره ولا كل ما له.","5:22":"إن الرب قد أعلن بصوت عظيم هذه الكلمات لكل جماعتكم في الجبل من وسط النار والسحاب ولم يزد. ونقشها على لوحين من حجر وأعطاني إياها.","5:23":"فلما سمعتم الصوت من وسط الظلام، والجبل يشتعل بالنار، أقبل علي جميع قادة أسباطكم وشيوخكم،","5:24":"وقالوا: قد أظهر الرب لنا مجده وعظمته، وسمعنا صوته من وسط النار، ورأينا في هذا اليوم أن الله يخاطب الإنسان فلا يموت.","5:25":"ولكن الآن، إن عدنا نسمع صوت الرب إلهنا فإن هذه النار العظيمة تلتهمنا. فلماذا نموت؟","5:26":"إذ أي بشري سمع صوت الله الحي يتكلم من وسط النار مثلنا وعاش؟","5:27":"فتقدم أنت واستمع كل ما ينطق به الرب إلهنا، وخاطبنا بجميع ما يكلمك به، فنستمع ونطيع.","5:28":"فسمع الرب حديثكم حين كلمتموني، وقال لي: لقد سمعت حديث الشعب الذي كلموك به. وقد أحسنوا في كل ما قالوه.","5:29":"ياليت قلبهم يظل متعلقا بي حتى يتقوني ويطيعوا جميع وصاياي دائما، لكي يتمتعوا هم وأولادهم بالخير إلى الأبد.","5:30":"اذهب وقل لهم: ارجعوا إلى خيامكم.","5:31":"وأما أنت فامثل هنا أمامي، فأكلمك بجميع الوصايا والشرائع والأحكام لتعلمها لهم فيعملوا بها في الأرض التي وهبتها لهم ليمتلكوها.","5:32":"فاحرصوا على العمل بكل ما أمركم به الرب إلهكم، لا تحيدوا يمينا أو شمالا.","5:33":"واسلكوا في كل الطريق التي أوصاكم بها الرب لتحيوا وتزدهروا وتمكثوا طويلا في الأرض التي ترثونها.","6:1":"وهذه هي الوصايا والفرائض والأحكام التي أمرني الرب إلهكم أن ألقنكم إياها، لتعملوا بها في الأرض التي أنتم ماضون إليها لترثوها.","6:2":"وبذلك تتقي الرب إلهك وتمارس جميع فرائضه ووصاياه التي أنا أوصيك بها أنت وابنك وحفيدك كل أيام حياتك فتطول أيامك.","6:3":"فأنصتوا يابني إسرائيل واحرصوا على العمل بها فتزدهروا وتتكاثروا جدا في أرض تفيض لبنا وعسلا، كما وعدكم الرب إله آبائكم.","6:4":"اسمعوا يابني إسرائيل: الرب إلهنا رب واحد،","6:5":"فأحبوا الرب إلهكم من كل قلوبكم ونفوسكم وقوتكم.","6:6":"وضعوا هذه الكلمات التي أوصيكم بها على قلوبكم،","6:7":"وقصوها على أولادكم، وتحدثوا بها حين تجلسون في بيوتكم، وحين تسيرون في الطريق، وحين تنامون، وحين تنهضون.","6:8":"اربطوها علامة على أيديكم، واجعلوها عصائب على جباهكم.","6:9":"اكتبوها على قوائم أبواب بيوتكم وبوابات مدنكم.","6:10":"ومتى أدخلكم الرب إلهكم إلى الأرض التي أقسم لآبائكم إبراهيم وإسحق ويعقوب أن يهبها لكم، حيث تنتشر مدن عظيمة لم تبنوها،","6:11":"وبيوت عامرة بخيرات لم تخزنوها، وآبار محفورة لم تحفروها، وأشجار كروم وزيتون لم تغرسوها، فأكلتم وشبعتم،","6:12":"فإياكم أن تنسوا الرب إلهكم الذي أطلقكم من عبودية ديار مصر.","6:13":"فالرب إلهكم تتقون، وإياه تعبدون، وباسمه تحلفون.","6:14":"لا تسيروا خلف آلهة أخرى من آلهة الأمم المحيطة بكم،","6:15":"لأن الرب إلهكم إله غيور حال في وسطكم، فيحتدم غضبه عليكم ويبيدكم عن وجه الأرض.","6:16":"لا تمتحنوا صبر الرب إلهكم، كما امتحنتموه في مسة.","6:17":"بل احفظوا وصايا الرب وشروطه وأحكامه التي أمركم بها،","6:18":"واصنعوا ما هو صالح ومرضي لدى الرب لتزدهروا وتدخلوا وترثوا الأرض التي أقسم الرب لآبائكم،","6:19":"أن يطرد جميع أعدائكم من أمامكم.","6:20":"وإذا سألكم أبناؤكم في مستقبل الأ يام: ما هي الشروط والفرائض والأحكام التي أمركم بها الرب إلهنا؟","6:21":"تجيبونهم: لقد كنا عبيدا لفرعون في مصر، فأخرجنا الرب بقوة فائقة،","6:22":"وأجرى الرب آيات وعجائب عظيمة ومهلكة بمصر على فرعون وجميع أهل بيته على مرأى منا.","6:23":"ثم أخرجنا من هناك ليأتي بنا ويورثنا الأرض التي أقسم لآبائنا أن يهبها لنا.","6:24":"فأمرنا الرب أن نمارس جميع هذه الفرائض ونتقيه لنزدهر دائما ونظل أحياء كما في هذا اليوم.","6:25":"وإذا أطعنا جميع هذه الوصايا بحرص لنمارسها أمام الرب إلهنا كما أمرنا، يكون لنا بر.","7:1":"ومتى أدخلكم الرب إلهكم إلى الأرض التي أنتم ماضون إليها لترثوها، وطرد من أمامكم سبع أمم، أكثر وأعظم منكم، وهم الحثيون والجرجاشيون والأموريون والكنعانيون والفرزيون والحويون واليبوسيون.","7:2":"وأسلمهم الرب إليكم وهزمتموهم، فإنكم تحرمونهم. لا تقطعوا لهم عهدا، ولا ترفقوا بهم،","7:3":"ولا تصاهروهم. فلا تزوجوا بناتكم من أبنائهم، ولا أبناءكم من بناتهم،","7:4":"إذ يغوون أبناءكم عن عبادتي ليعبدوا آلهة أخرى، فيحتدم غضب الرب عليكم ويهلككم سريعا.","7:5":"ولكن هذا ما تفعلونه بهم: اهدموا مذابحهم وحطموا أصنامهم وقطعوا سواريهم وأحرقوا تماثيلهم.","7:6":"لأنكم شعب مقدس للرب إلهكم. فإياكم قد اختار الرب إلهكم من بين جميع شعوب الأرض لتكونوا شعبه الخاص.","7:7":"ولم يفضلكم الرب ويتخيركم لأنكم أكثر عددا من سائر الشعوب، فأنتم أقل الأمم عددا.","7:8":"بل من محبته، وحفاظا على القسم الذي أقسم به لآبائكم، أخرجكم بقوة فائقة، وفداكم من نير عبودية فرعون ملك مصر.","7:9":"فاعلموا أن الرب إلهكم هو الله ، الإله الأمين الوفي بالعهد والإحسان لمحبيه وحافظي وصاياه إلى ألف جيل.","7:10":"وهو يجازي مبغضيه علنا، فيستأصلهم ولا يتمهل، بل يسرع في معاقبة من يبغضه.","7:11":"فأطيعوا الوصايا والفرائض والأحكام التي أوصيكم بها اليوم لتمارسوها.","7:12":"فإن استمعتم إلى هذه الأحكام وأطعتموها وعملتم بها، فإن الرب إلهكم يحافظ لكم على العهد والإحسان كما حلف لآبائكم.","7:13":"ويحبكم ويبارككم ويكثركم، ويبارك ثمرة أحشائكم وغلة أرضكم من قمح وزيت، ويزيد من إنتاج بقركم ونعاجكم على الأرض التي أقسم لآبائكم أن يهبها لكم.","7:14":"وتكونون مباركين أكثر من جميع الشعوب، فلا يوجد عقيم ولا عاقر فيكم ولا في بهائمكم.","7:15":"ويقيكم الرب من كل علة، وكل أمراض مصر الخبيثة التي عاينتموها، ولا يصيبكم بها، بل يجعلها على مبغضيكم.","7:16":"وتستأصلون جميع الشعوب الذين يسلمهم الرب إليكم، فلا تشفقوا عليهم ولا تعبدوا آلهتهم لأن ذلك شرك لكم.","7:17":"وإن تساءلتم في قلوبكم: إن هذه الشعوب أكثر منا عددا، فكيف نقدر أن نطردهم؟","7:18":"لا تخافوا منهم بل اذكروا ما صنعه الرب إلهكم بفرعون وسائر المصريين.","7:19":"اذكروا الويلات العظيمة التي شهدتها أعينكم والمعجزات والعجائب والقوة الشديدة والقدرة الفائقة التي أخرجكم بها الرب إلهكم، فهكذا يفعل الرب إلهكم بجميع الأمم التي تخشونها.","7:20":"ويرسل عليهم الرب إلهكم الزنابير ويبيد الباقين والمحتجبين من وجهكم.","7:21":"لا ترهبوهم، لأن الرب إلهكم الحال بينكم إله عظيم ومرهوب.","7:22":"غير أن الرب إلهكم سيطرد تلك الأمم من أمامكم تدريجيا، لئلا تتكاثر عليكم وحوش البرية إن أسرعتم بالقضاء عليهم دفعة واحدة.","7:23":"إن الرب إلهكم يسلمهم إليكم موقعا بهم الاضطراب العظيم حتى ينقرضوا،","7:24":"ويجعل ملوكهم يقعون في أسركم فتمحون اسمهم من الأرض. ولن يقدر أحد أن يجابهكم، فإنكم تفنونهم.","7:25":"أحرقوا تماثيل آلهتهم ولا تشتهوا ما عليها من فضة وذهب فتغنموها لأنفسكم، لئلا تقتنصكم، لأنها رجس عند الرب إلهكم.","7:26":"لا تدخلوا شيئا رجسا إلى بيوتكم لئلا تصبحوا أهلا للدمار مثله، بل عليكم أن تستقبحوه وتمقتوه، لأن مآله الدمار.","8:1":"فاحفظوا جميع الوصايا التي أوصيكم بها اليوم لتمارسوها، فتحيوا وتتكاثروا وتدخلوا لامتلاك الأرض التي أقسم الرب عليها لآبائكم.","8:2":"وتذكروا كيف قادكم الرب إلهكم في كل طريق الصحراء هذه الأربعين سنة ليذلكم ويمتحنكم، فيعرف ما في قلوبكم: إن كنتم تحفظون أوامره أم تعصونه.","8:3":"فأذلكم ثم أجاعكم وأطعمكم المن الذي لم تكونوا تعرفونه، لا أنتم ولا آباؤكم ليعلمكم أنه ليس بالخبز وحده يحيا الإنسان، بل بكل كلمة ينطق بها فم الرب.","8:4":"وفي غضون الأربعين سنة لم تبل ثيابكم عليكم، ولم تتورم أقدامكم.","8:5":"فاعلموا إذا في قلوبكم أن الرب إلهكم قد أدبكم كما يؤدب المرء ابنه.","8:6":"فأطيعوا وصايا الرب إلهكم لتسلكوا في سبله واتقوه.","8:7":"لأن الرب إلهكم آت بكم إلى أرض خصيبة، تكثر فيها الأنهار والآبار، وعيون ماء تتدفق في الوديان والجبال.","8:8":"إلى أرض حنطة وشعير وكروم وتين ورمان وزيتون وعسل.","8:9":"إلى أرض لا تأكلون بالذل خبزكم ولا يعوزكم فيها شيء. هي أرض يتوافر في حجارتها الحديد، ومن جبالها تستخرجون النحاس.","8:10":"فمتى أكلتم وشبعتم باركوا الرب إلهكم الذي وهبكم هذه الأرض الخصيبة.","8:11":"إياكم نسيان الرب إلهكم وإهمال وصاياه وأحكامه وفرائضه التي أوصيكم اليوم بها،","8:12":"لئلا إذا أكلتم وشبعتم وبنيتم بيوتا جميلة سكنتموها،","8:13":"وتكاثرت أبقاركم وغنمكم وذهبكم وجميع ما لكم.","8:14":"تتكبر قلوبكم وتنسون الرب إلهكم الذي أطلقكم من نير عبودية ديار مصر،","8:15":"والذي قادكم في الصحراء الشاسعة المهولة، حيث تكمن أفاع سامة وعقارب وعطش لخلوها من الماء، ففجر لكم ماء من صخرة الصوان.","8:16":"الذي أطعمكم في الصحراء المن الذي لم يعرفه آباؤكم ليذلكم ويمتحنكم، فيحسن إليكم في آخرتكم،","8:17":"خوفا من أن تقولوا في قلوبكم: لقد أحرزنا هذا الثراء بفضل قوتنا وقدرة أيدينا.","8:18":"ولكن اذكروا أن الرب إلهكم هو الذي يمنحكم القوة لإحراز الثروة، وفاء بوعده الذي أقسم عليه لآبائكم كما في هذا اليوم.","8:19":"أما إن نسيتم الرب إلهكم، وغويتم وراء آلهة أخرى وعبدتموها وسجدتم لها، فإنني أشهد عليكم أنكم لا محالة هالكون.","8:20":"كالأمم التي يبيدها الرب من أمامكم هكذا أنتم أيضا تبيدون، لأنكم لم تطيعوا أمر الرب إلهكم.","9:1":"استمعوا يابني إسرائيل: أنتم على وشك عبور نهر الأردن لتدخلوا لطرد شعوب أكبر وأعظم منكم، وللاستيلاء على مدن عظيمة محصنة بأسوار تبلغ عنان السماء،","9:2":"يقيم فيها العناقيون الجبابرة العمالقة الذين عرفتم عنهم وسمعتم من يقول: من يستطيع أن يتحدى العناقيين؟","9:3":"فاعلموا اليوم أن الرب إلهكم يتقدمكم كنار آكلة، وهو الذي يستأصلهم ويذلهم أمامكم، فتطردونهم وتبيدونهم سريعا كما كلمكم الرب.","9:4":"لا تقولوا لأنفسكم بعد أن ينفيهم الرب من أمامكم: لقد أدخلنا الرب لامتلاك هذه الأرض بفضل صلاحنا. إنما من أجل كثرة إثمهم يطردهم الرب إلهكم من أمامكم.","9:5":"إذ ليس بفضل صلاحكم واستقامتكم تدخلون لامتلاك أرضهم، إنما من أجل إثمهم يطردهم الرب إلهكم من أمامكم وفاء بوعده الذي أقسم عليه لآبائكم إبراهيم وإسحق ويعقوب.","9:6":"فاعلموا أنه ليس بفضل صلاحكم يهبكم الرب إلهكم هذه الأرض الخصيبة لامتلاكها، لأنكم شعب عنيد.","9:7":"اذكروا ولا تنسوا كيف أسخطتم الرب إلهكم عليكم في الصحراء، فمنذ أن غادرتم ديار مصر حتى بلغتم هذا المكان وأنتم تقاومون الرب.","9:8":"ففي جبل حوريب أثرتم غيظ الرب، فاحتدم غضبه عليكم حتى أوشك أن يفنيكم.","9:9":"فحين صعدت إلى الجبل لأتسلم لوحي حجر العهد الذي قطعه الرب معكم، وأقمت فيه أربعين نهارا وأربعين ليلة لا آكل فيها خبزا أو أشرب ماء،","9:10":"وسلمني الرب لوحي الحجر المكتوبين بأصبع الله، حيث خط عليهما جميع الوصايا التي كلمكم بها الرب في الجبل من وسط النار في يوم الاجتماع.","9:11":"وحين أعطاني الرب لوحي حجر العهد في نهاية الأربعين نهارا والأربعين ليلة،","9:12":"قال لي الرب: قم وأسرع بالنزول من هنا، لأن شعبك الذي أخرجته من مصر قد ضل، وزاغوا سريعا عن السبيل الذي أوصيتهم به، إذ صاغوا لأنفسهم تمثالا مسبوكا.","9:13":"ثم قال لي: قد تأملت هذا الشعب وإذ به شعب متصلب القلب.","9:14":"دعني أستأصلهم وأمحو اسمهم من تحت السماء، وأقيم منك شعبا أعظم وأكثر منهم.","9:15":"فانصرفت، وانحدرت من الجبل وهو ما برح يشتعل بالنار، ولوحا العهد في يدي.","9:16":"وتطلعت وإذا بكم قد أخطأتم إلى الرب، وصغتم لأنفسكم عجلا مسبوكا، وضللتم سريعا عن السبيل الذي أوصاكم به الرب.","9:17":"فأخذت اللوحين وألقيتهما من يدي وحطمتهما أمام أعينكم.","9:18":"ثم انطرحت بذل أمام الرب أربعين نهارا وأربعين ليلة، كما في السابق، لا آكل خبزا ولا أشرب ماء، من جراء كل خطاياكم التي ارتكبتموها في عيني الرب لتغيظوه،","9:19":"لأنني جزعت من غضب الرب واحتدام سخطه عليكم، حتى أوشك أن يبيدكم. فاستجاب لي الرب أيضا في تلك المرة.","9:20":"كما غضب الرب على هرون أيضا حتى كاد أن يهلكه، فصليت من أجله حينئذ، فقبل الرب تضرعي.","9:21":"أما خطيئتكم، العجل الذي سبكتموه، فقد أخذته وأحرقته ودققته وطحنته جيدا، حتى استحال إلى غبار، ثم طرحت غباره في النهر المنحدر من الجبل.","9:22":"وما لبثتم أن أسخطتم الرب في تبعيرة ومسة وقبروت هتأوة.","9:23":"وحين أرسلكم الرب من قادش برنيع وأمر: اصعدوا لامتلاك الأرض التي وهبتها لكم، عصيتم أمر الرب إلهكم ولم تصدقوه، ولم تأتمروا بقوله،","9:24":"فأنتم حقا متمردون على الرب منذ أن عرفتكم.","9:25":"فسقطت أمام الرب أربعين نهارا وأربعين ليلة، لأن الرب أعلن أنه عازم أن يقضي عليكم.","9:26":"وابتهلت إلى الرب قائلا: ياسيد الرب، لا تهلك شعبك وميراثك الذي افتديته بقوتك العظيمة، وأخرجته من مصر بقدرة فائقة.","9:27":"اذكر عبيدك إبراهيم وإسحق ويعقوب، وتغاض عن عناد هذا الشعب وإثمه وخطيئته،","9:28":"لئلا يقول أهل مصر الذين أخرجتنا من بينهم: لقد أخرجهم الرب ليهلكهم في البرية، لأنه عجز عن إدخالهم إلى الأرض التي وعدهم بها، ولأنه مقتهم.","9:29":"إنهم شعبك وميراثك الذي أخرجته بقوتك العظيمة وقدرتك الفائقة.","10:1":"وقال لي الرب: انحت لك لوحين من حجر مثل اللوحين الأولين، واصعد إلى الجبل، واصنع لك تابوتا من خشب،","10:2":"فأخط على اللوحين الوصايا التي كانت مكتوبة على اللوحين الأولين اللذين حطمتهما، فتضعهما في التابوت.","10:3":"فصنعت تابوتا من خشب السنط، ونحت لوحين من حجر مثل اللوحين الأولين، وصعدت إلى الجبل واللوحان في يدي.","10:4":"فخط الرب على اللوحين ما كان قد خطه سابقا، الوصايا العشر التي كلمكم بها الرب في الجبل من وسط النار في يوم الاجتماع، وسلمني إياها.","10:5":"ثم انصرفت، وانحدرت من الجبل، ووضعت اللوحين في التابوت الذي صنعته. وها هما هناك، كما أمر الرب.","10:6":"ثم ارتحل الإسرائيليون من جوار آبار بني يعقان إلى موسير، حيث مات هرون ودفن هناك. فتولى ألعازار ابنه رئاسة الكهنوت عوضا عنه.","10:7":"ومن هناك انتقل الإسرائيليون إلى الجدجود، ومنها إلى يطبات، وهي أرض عامرة بالأنهار.","10:8":"في ذلك الوقت خصص الرب سبط لاوي لحمل تابوت عهد الرب والمثول أمام الرب ليخدموه ويباركوا اسمه إلى هذا اليوم.","10:9":"لهذا لم يرث اللاويون مع بقية إخوتهم لأن الرب هو نصيبهم كما وعدهم.","10:10":"أما أنا فقد مكثت في الجبل أربعين نهارا وأربعين ليلة، كما حدث في المرة الأولى واستجاب لي الرب أيضا فلم يهلككم","10:11":"ثم قال لي الرب: قم وامض للارتحال أمام الشعب، للدخول وامتلاك الأرض التي حلفت لآبائهم أن أهبها لهم.","10:12":"فالآن أيها الإسرائيليون ماذا يطلب منكم الرب إلهكم سوى أن تتقوه وتسلكوا في كل طرقه، وتحبوه وتعبدوه من كل قلوبكم ومن كل نفوسكم،","10:13":"وتطيعوا وصاياه وفرائضه، التي أنا أوصيكم بها اليوم لخيركم؟","10:14":"فالرب إلهكم هو مالك السموات وسماء السموات وكل ما فيها.","10:15":"غير أن الرب فضل آباءكم واصطفى ذريتهم من بعدهم، التي هي أنتم، لتكونوا فوق جميع أمم الأرض، كما هو حادث اليوم.","10:16":"فطهروا قلوبكم الأثيمة، وأقلعوا عن عنادكم،","10:17":"لأن الرب إلهكم هو إله الآلهة ورب الأرباب، الإله العظيم الجبار المهيب، الذي لا يحابي وجه أحد، ولا يرتشي.","10:18":"إنه يقضي حق اليتيم والأرملة، ويحب الغريب فيوفر له طعاما وكساء","10:19":"فأحبوا الغريب لأنكم كنتم غرباء في ديار مصر.","10:20":"اتقوا الرب إلهكم وإياه اعبدوا وبه اعتصموا وباسمه احلفوا،","10:21":"فهو فخركم وإلهكم الذي أجرى معكم تلك المعجزات العظيمة التي شهدتها أعينكم.","10:22":"فعندما انحدر آباؤكم إلى مصر كانوا سبعين نفسا، والآن قد جعلكم الرب إلهكم في كثرة النجوم.","11:1":"فأحبوا الرب إلهكم وحافظوا على حقوقه، وأطيعوا فرائضه وأحكامه ووصاياه دائما.","11:2":"واعلموا اليوم أن حديثي ليس موجها لأبنائكم الذين لم يعرفوا ولا اختبروا تأديب الرب إلهكم، ولا شهدوا عظمته وقوته الشديدة وقدرته الفائقة،","11:3":"ولا آياته ومعجزاته التي أجراها في مصر على فرعون ملك مصر وعلى أرضه،","11:4":"والتي صنعها بجيش مصر وخيلهم ومركباتهم، حيث جعل مياه البحر الأحمر تغمرهم حين سعوا وراءكم، فأهلكهم الرب.","11:5":"والتي عملها لكم في الصحراء حتى وصلتم إلى هذا المكان،","11:6":"وا لتي أنزلها بداثان وأبيرام ابني أليآب من سبط رأوبين، اللذين انشقت الأرض وابتلعتهما مع عائلتيهما وخيامهما وممتلكاتهما، على مشهد كل الإسرائيليين،","11:7":"بل لكم خاصة لأن أعينكم أنتم هي التي شهدت عظائم الرب التي أجراها.","11:8":"لهذا أطيعوا كل الوصايا التي أوصيتكم بها اليوم، لتكون لديكم القوة لدخول وامتلاك الأرض التي أنتم ماضون إليها لترثوها،","11:9":"ولكي تطيلوا أيامكم على الأرض التي أقسم الرب لآبائكم أن يعطيها لهم ولنسلهم، أرض تفيض لبنا وعسلا.","11:10":"لأن الأرض التي توشكون الدخول إليها لامتلاكها لا تماثل أرض مصر التي خرجتم منها، حيث كنتم تزرعون زرعكم وتروونه (بفتح سدود القنوات الصغيرة) بأرجلكم، وكأنه بستان بقول.","11:11":"بل الأرض التي أنتم مقبلون عليها لامتلاكها هي أرض جبال وأودية، ترتوي من مطر السماء.","11:12":"أرض يعتني بها الرب إلهكم، إذ ترعاها عيناه دائما من أول السنة حتى آخرها.","11:13":"فإذا أطعتم الوصايا التي أوصيكم بها اليوم، وأحببتم الرب إلهكم وعبدتموه من كل قلوبكم ومن كل نفوسكم،","11:14":"فإن الرب يسكب على أرضكم المطر المبكر والمتأخر في أوانه، فتجمعون حنطتكم وخمركم، وزيتكم،","11:15":"وينبت لبهائمكم عشبا في حقولكم، فتأكلون أنتم وتشبعون.","11:16":"ولكن إياكم أن تغوي قلوبكم فتزيغوا وتعبدوا آلهة أخرى وتسجدوا لها،","11:17":"فيحتدم غضب الرب عليكم، ويوصد السماء، ويمنع المطر عن الانهمار، فتجدب الأرض ولا تغل فتفنون سريعا عن الأرض الخصيبة التي وهبها لكم الرب.","11:18":"فثبتوا كلماتي هذه على قلوبكم، واربطوها علامة على أيديكم، واعصبوا بها جباهكم،","11:19":"وعلموها لأولادكم، وتحدثوا بها حين تكونون في بيوتكم، وحين تسيرون في الطريق، وحين تأوون إلى فراشكم، وحين تنهضون،","11:20":"واكتبوها على قوائم أبواب بيوتكم وبوابات مدنكم،","11:21":"لكي تطول أيامكم وأيام أولادكم على الأرض التي حلف الرب لآبائكم أن يهبها لهم، فتكون في كثرتها كأيام السماء على الأرض.","11:22":"لأنه إذا أطعتم جميع هذه الوصايا التي أنا أوصيكم بها لتمارسوها، وأحببتم الرب وسلكتم في جميع سبله وتمسكتم به،","11:23":"يطرد الرب جميع تلك الأمم من أمامكم، فترثون شعوبا أكبر وأعظم منكم.","11:24":"وكل موضع تطأه أقدامكم يصبح لكم، فتكون حدودكم من الصحراء في الجنوب إلى لبنان، ومن نهر الفرات إلى البحر الأبيض المتوسط غربا.","11:25":"ولا يجرؤ إنسان أن يقاومكم، لأن الرب إلهكم يجعل الخوف والرعب منكم يسودان على كل الأرض التي تطأونها، كما وعدكم.","11:26":"انظروا ها أنا أخيركم اليوم بين البركة واللعنة:","11:27":"البركة لكم إن أطعتم وصايا الرب إلهكم التي أنا أوصيتكم بها اليوم،","11:28":"واللعنة إن عصيتم وصايا الرب إلهكم، وضللتم عن الطريق التي أنا أوصيكم بها اليوم، وغويتم وراء آلهة أخرى غريبة عنكم.","11:29":"إذا أتى بكم الرب إلى الأرض التي توشكون الدخول إليها لامتلاكها، فأعلنوا البركة من على جبل جرزيم، واللعنة من على جبل عيبال.","11:30":"أو ليس هما في غربي نهر الأردن، وراء الطريق المتجهة نحو غروب الشمس في أرض الكنعانيين المستوطنين في العربة مقابل الجلجال عند بلوطات مورة؟","11:31":"لأنكم عابرون نهر الأردن لتدخلوا لامتلاك الأرض التي يهبها لكم الرب إلهكم، فترثونها وتقيمون فيها.","11:32":"فأطيعوا جميع الفرائض والأحكام التي سننتها اليوم أمامكم لتمارسوها.","12:1":"إليكم الفرائض والأحكام التي عليكم ممارستها في الأرض التي وهبها لكم الرب إله آبائكم لترثوها كل أيام حياتكم على الأرض:","12:2":"دمروا جميع الأماكن التي ترثونها، حيث عبدت الأمم آلهتها، سواء كانت على الجبال الشامخة أم على التلال أم تحت كل شجرة خضراء،","12:3":"واهدموا مذابحهم، وحطموا أنصابهم، وأحرقوا سواريهم. فتتوا تماثيل آلهتهم وامحوا أسماءهم من ذلك المكان،","12:4":"ولا تمارسوا أساليبهم عندما تعبدون الرب إلهكم،","12:5":"بل اطلبوا المكان الذي يختاره الرب إلهكم وسط أسباطكم ليضع عليه اسمه، ويكون مقر سكناه. إليه تذهبون،","12:6":"وتقدمون محرقاتكم وذبائحكم وعشوركم وتقدماتكم ونذوركم وقرابينكم الطوعية وأبكار بقركم وغنمكم،","12:7":"فتأكلون هناك أنتم وعائلاتكم لدى الرب، وتفرحون بكل ما تمتد إليه أيديكم، لأن الرب إلهكم قد بارككم.","12:8":"لا يصنع كل واحد منكم ما يستحسنه كما هو حادث اليوم،","12:9":"لأنكم لم تدخلوا بعد إلى موضع الراحة والميراث الذي يهبه لكم الرب إلهكم.","12:10":"ولكن متى اجتزتم نهر الأردن واستوطنتم الأرض التي وهبها لكم الرب إلهكم، وأراحكم من جميع أعدائكم المحيطين بكم، وسكنتم آمنين،","12:11":"فاحملوا جميع ما أوصيتكم به من محرقات وذبائح وعشور وتقدمات أيديكم وقرابين طوعية، التي تنذرونها للرب إلى المكان الذي يختاره الرب إلهكم ليحل فيه اسمه،","12:12":"وهناك احتفلوا أنتم وبنوكم وبناتكم وعبيدكم وإماؤكم واللاوي المقيم في جواركم، لأنه ليس له نصيب أو ميراث خاص به.","12:13":"إياكم أن تقدموا محرقاتكم في أي مكان ترغبون فيه،","12:14":"إنما تصعدون محرقاتكم وتمارسون ما أوصيتكم به في المكان الذي يختاره الرب في أرض أحد أسباطكم.","12:15":"اذبحوا في أي من مدنكم أيا من الحيوانات، وكلوا من لحومها بقدر ما تشاؤون كالظبي والأيل حسب بركة الرب إلهكم. يأكل منها الإنسان الطاهر والنجس على حد سواء.","12:16":"وأما الدم فلا تأكلوه، بل اسكبوه على الأرض كما تسكبون الماء،","12:17":"احذروا أن تأكلوا في مدنكم عشور حنطتكم وخمركم وزيتكم، ولا أبكار بقركم وغنمكم، ولا شيئا من نذوركم أو قرابينكم الطوعية وتقدمات أيديكم.","12:18":"بل تأكلونها أنتم وأبناؤكم وبناتكم وعبيدكم وإماؤكم واللاويون المقيمون في جواركم لدى الرب إلهكم في المكان الذي يختاره الرب إلهكم، وتحتفلون أمامه بكل ما تمتلكه أيديكم","12:19":"إياكم إهمال اللاويين طوال بقائكم على أرضكم.","12:20":"وإذا وسع الرب إلهكم حدود أرضكم كما وعدكم، واشتهت أنفسكم اللحم، وقلتم: نود أكل اللحم. فمن كل ما تشتهيه أنفسكم من اللحم كلوا.","12:21":"وإذا كان الموضع الذي يختاره الرب إلهكم ليضع فيه اسمه بعيدا عن مكان سكنى بعضكم، فاذبحوا من بقركم وغنمكم التي أنعم بها الرب عليكم كما أوصيتكم، وكلوا في مدنكم من كل ما اشتهته أنفسكم","12:22":"كلوه كما يؤكل الظبي والأيل. يأكل منه الإنسان الطاهر والنجس على حد سواء.","12:23":"لكن إياكم وأكل الدم، لأن الدم هو النفس. فلا تأكلوا النفس مع اللحم.","12:24":"لا تأكلوا منه بل اسكبوه على الأرض كما يسكب الماء.","12:25":"لا تأكلوه، لتنعموا أنتم وأولادكم من بعدكم بالخير، إذ صنعتم الحق في عيني الله.","12:26":"أما ما تقدسونه من أشياء، ونذوركم فتحملونها وتمضون إلى المكان الذي يختاره الرب","12:27":"فتقدمون محرقاتكم، اللحم والدم على مذبح الرب إلهكم، فيسكب دمها على مذبح الرب. أما اللحم فتأكلونه.","12:28":"فاحفظوا وأطيعوا جميع هذه الوصايا التي أنا أوصيكم بها لتتمتعوا أنتم وأولادكم من بعدكم بالخير إلى الأبد، إذ عملتم الصالح والحق في عيني الرب إلهكم.","12:29":"ومتى استأصل الرب إلهكم من أمامكم الأمم التي توشكون على غزوهم، وطردهم، ثم ورثتموهم واستوطنتم في أرضهم،","12:30":"فاحذروا من الوقوع في الشرك، باتباع عباداتهم من بعد فنائهم من أمامكم، ومن ممارسة مراسيم عبادة آلهتهم قائلين: كما عبد هؤلاء الأمم آلهتهم هكذا نفعل نحن أيضا.","12:31":"لا تصنع هكذا للرب إلهك، لأنهم قد ارتكبوا في عبادة آلهتهم كل ما يمقته الرب من الأرجاس، إذ أحرقوا بالنار أبناءهم وبناتهم في سبيل آلهتهم،","12:32":"فاحرصوا على طاعة كل ما أوصيكم به. لا تزيدوا عليه ولا تنقصوا منه.","13:1":"إذا ظهر بينكم نبي أو صاحب أحلام، وتنبأ بوقوع آية أو أعجوبة.","13:2":"فتحققت تلك الآية أو الأعجوبة التي تنبأ بها، ثم قال: هلم نذهب وراء آلهة أخرى لم تعرفوها ونعبدها.","13:3":"فلا تصغوا إلى كلام ذلك النبي أو صاحب الأحلام، لأن الرب إلهكم يجربكم ليرى إن كنتم تحبونه من كل قلوبكم ومن كل أنفسكم،","13:4":"فاتبعوا الرب إلهكم واتقوه، وأطيعوا وصاياه واسمعوا صوته، واعبدوه وتمسكوا به.","13:5":"أما ذلك النبي أو الحالم فإنه يقتل، لأنه نطق بالبهتان ضد الرب إلهكم الذي أخرجكم من ديار مصر، وفداكم من نير العبودية، ليضلكم عن الطريق التي أمركم بسلوكها، فتستأصلون الشر من بينكم.","13:6":"وإذا أضلك سرا أخوك ابن أمك، أو ابنك أو ابنتك، أو زوجتك المحبوبة، أو صديقك الحميم قائلا: لنذهب ونعبد آلهة أخرى غريبة عنك وعن آبائك","13:7":"من آلهة الشعوب الأخرى المحيطة بك أو البعيدة عنك من أقصى الأرض إلى أقصاها،","13:8":"فلا تستجب له ولا تصغ إليه، ولا يشفق قلبك عليه، ولا تترَأف به، ولا تتستر عليه.","13:9":"بل حتما تقتله. كن أنت أول قاتليه، ثم يعقبك بقية الشعب.","13:10":"ارجمه بالحجارة حتى يموت، لأنه سعى أن يضلك عن الرب إلهك الذي أخرجك من ديار مصر من نير العبودية،","13:11":"فيشيع الخبر بين الإسرائيليين جميعهم ويخافون، ولا يعاودون ارتكاب مثل هذا الأمر الشنيع بينكم.","13:12":"إن سمعتم عن إحدى مدنكم التي يهبها الرب إلهكم لتسكنوا فيها،","13:13":"أن بعض الفاسقين قد خرجوا من بينكم وضللوا سكان مدينتهم قائلين: لنذهب ونعبد آلهة أخرى غريبة عنكم","13:14":"فافحصوا الأمر أولا وتحققوا منه بدقة. فإن تبين لكم صدقه، وثبت أن هذا الأمر الشنيع قد جرى فعلا،","13:15":"فاقضوا قضاء على سكان تلك المدينة وعلى بهائمهم واقتلوهم بحد السيف.","13:16":"واجمعوا كل أمتعتها وكوموها في وسط ساحتها وأحرقوا المدينة مع كل أمتعتها كاملة، انتقاما للرب، فتصبح تلا خرابا إلى الأبد لا تبنى بعد.","13:17":"ولا يعلق شيء بأيديكم مما هو محرم منها، ليخمد الرب من احتدام غضبه ويمنحكم رحمة، فيبارككم ويكثركم كما أقسم لآبائكم،","13:18":"إن سمعتم لصوت الرب إلهكم وأطعتم وصاياه التي أنا أوصيكم اليوم بها لتعملوا الحق في عيني الرب إلهكم.","14:1":"أنتم أبناء للرب إلهكم، فلا تجرحوا أجسادكم، ولا تحلقوا مقدمة رؤوسكم حزنا على ميت،","14:2":"لأنكم شعب مقدس للرب إلهكم، وقد اختاركم من بين شعوب الأرض كافة لتكونوا له شعبا خاصا.","14:3":"لا تأكلوا شيئا رجسا.","14:4":"أما البهائم التي تأكلون منها فهي: البقر والضأن والمعز","14:5":"والأيل والظباء وبعض أنواع الوعول والغزلان البيضاء، والبقر الوحشي،","14:6":"وكل بهيمة ذات ظلف مشقوق ومجترة تأكلونها.","14:7":"ولكن لا تأكلوا الحيوانات المجترة غير مشقوقة الظلف، كالجمل والأرنب والوبر، فإنها تجتر ولكنها غير مشقوقة الظلف، لذلك هي نجسة لكم،","14:8":"والخنزير لأنه مشقوق الظلف ولكنه غير مجتر، لذلك فهو نجس لكم. فلا تأكلوا من لحم جميع هذه البهائم ولا تلمسوا جثثها.","14:9":"أما ما يعيش في الماء فكلوا من كل ما له زعانف وقشور،","14:10":"ولكن لا تأكلوا مما ليس له زعانف وقشور لأنه نجس لكم.","14:11":"كلوا من كل طير طاهر،","14:12":"ولكن من الطيور التالية لا تأكلوا: النسر والأنوق والعقاب","14:13":"والحدأة والباشق والشاهين بمختلف أنواعه،","14:14":"وجميع أصناف الغربان،","14:15":"والنعامة والظليم والسأف وكل أجناس الباز،","14:16":"والبوم والكركي والبجع،","14:17":"والقوق والرخم والغواص،","14:18":"واللقلق والببغاء على مختلف أنواعه، والهدهد والخفاش.","14:19":"وكل حشرة تطير، هي نجسة لكم. لا تأكلوها.","14:20":"ولكن كلوا من كل طير طاهر.","14:21":"لا تأكلوا جثة حيوان ميت، بل أعطوها للغريب المقيم في جواركم فيأكلها أو يبيعها لأجنبي، لأنكم شعب مقدس للرب إلهكم. لا تطبخوا جديا بلبن أمه.","14:22":"قدموا عشور محاصيلكم التي تغلها حقولكم كل سنة،","14:23":"وكلوا عشور حنطتكم وخمركم وزيوتكم وأبكار بقركم وغنمكم لدى الرب، في الموضع الذي يختاره ليحل اسمه فيه، لتتعلموا أن تتقوا الرب إلهكم دائما.","14:24":"ولكن إن كانت الطريق إلى موضع سكنى الرب طويلة، بحيث يتعذر عليكم حمل عشوركم إليه، وإذا كان المكان الذي يختاره الرب إلهكم ليجعل اسمه فيه بعيدا عليكم، وكان الرب قد بارككم،","14:25":"فبيعوا عشور غلاتكم بفضة وصروها وامضوا إلى الموضع الذي يختاره الرب إلهكم،","14:26":"وأنفقوا الفضة على ما تشتهيه أنفسكم من بقر وغنم وخمر ومسكر وكل ما ترغبون فيه، واحتفلوا أنتم وأهل بيوتكم لدى الرب إلهكم.","14:27":"ولا تهملوا اللاويين المقيمين في مدنكم لأنهم لم يرثوا ملكا أو نصيبا معكم.","14:28":"وفي نهاية كل ثلاث سنين، أخرجوا عشور محصول السنة الثالثة واخزنوها في مدنكم،","14:29":"فيقبل اللاويون الذين لم يرثوا ملكا أو نصيبا معكم، والغريب واليتيم والأرملة، المقيمون في مدنكم فيأكلون ويشبعون ليبارككم الرب إلهكم في كل ما تنتجه أيديكم.","15:1":"وفي آخر كل سنة سابعة تبريء المديونين من الديون","15:2":"وهذا هو الإجراء: يقوم كل دائن بإبراء مدينه مما أقرضه، ولا يطالب أخاه الإسرائيلي به، لأنه قد نودي بوقت الرب لإلغاء الديون.","15:3":"أما الأجنبي فتطالبه بالدين، وأما أخوك فتبرئه من ديونه.","15:4":"ولكن لن يكون فقير بينكم، لأن الرب سيبارك الأرض التي ورثها لكم ملكا.","15:5":"فإن سمعتم صوت الرب إلهكم وأطعتم، وعملتم بكل ما أنا أوصيتكم به اليوم،","15:6":"فإن الرب إلهكم يبارككم كما وعد، فتقرضون أمما كثيرة ولا تقترضون من أحد، وتتسلطون على أمم كثيرة ولا يتسلط أحد عليكم.","15:7":"إن وجد بينكم إسرائيلي فقير مقيم في أي مدينة من مدن الأرض التي سيهبها لكم الرب إلهكم، فلا تقسوا قلوبكم وتمتنعوا عن إعانته،","15:8":"بل اسخوا عليه وأقرضوه مقدار ما يحتاج إليه.","15:9":"إياكم أن تحدثوا قلوبكم بخبث قائلين: ها قد قربت السنة السابعة، سنة الإبراء من الديون فيسوء الأمر في أعينكم وتمتنعون عن إقراضه. فإن فعلتم هذا فإنه يستغيث بالرب عليكم، فتصبحون مذنبين في حكم الرب.","15:10":"أقرضوه عن طيب خاطر، لأنه من أجل هذا يبارككم الرب إلهكم في كل أعمالكم وما تنتجه أيديكم،","15:11":"فالأرض لن تخلو أبدا من الفقراء، لهذا أوصيكم أن تسخوا على أخيكم المسكين والفقير المقيم في أرضكم.","15:12":"إذا اشتريت عبرانيا أو عبرانية، وخدمك ست سنوات، ففي السنة السابعة تطلقه حرا من عندك.","15:13":"لا تطلقه صفر اليدين،","15:14":"بل زوده مما باركك الرب إلهك به، من غنم وحنطة وزيت.","15:15":"واذكروا أنكم كنتم عبيدا في ديار مصر، فحرركم الرب إلهكم. لذلك أوصيكم بهذا الأمر اليوم.","15:16":"ولكن إن قال لك العبد: إنني لا أريد أن أتركك لأنه قد أحبك وأحب بيتك وتمتع بالخير عندك،","15:17":"فخذ مثقبا واثقب به أذنه أمام قضاة المدينة، فيصبح لك عبدا مدى حياته. وكذلك تفعل بأمتك.","15:18":"لا يصعب عليك إطلاقه حرا من عندك، لأنه قد خدمك في ست سنوات بما يعادل ضعفي أجرة الأجير، وبذلك يباركك الرب إلهك في كل ما تعمله.","15:19":"خصص للرب كل بكر ذكر من بقرك ومن غنمك. لا تستخدم بكر بقرك ولا تجز صوف بكر غنمك،","15:20":"بل عليك أن تأكله أنت وأهل بيتك، كل سنة بسنتها، في الموضع الذي يختاره الرب.","15:21":"ولكن إن كان في البكر عيب من عرج أو عمى أو أي عيب، فلا تذبحه للرب إلهك،","15:22":"بل تأكله في مدينتك، الطاهر والنجس على حد سواء، فتأكلونه كما تأكلون الظبي والأيل.","15:23":"أما دمه فاسكبوه على الأرض ولا تأكلوا منه.","16:1":"احتفلوا دائما بفصح الرب إلهكم في شهر أبيب (أي شهر نيسان - أبريل)، ففي هذا الشهر أخرجكم الرب إلهكم من مصر ليلا.","16:2":"واذبحوا للرب إلهكم غنما أو بقرا في الموضع الذي يختاره الرب ليحل اسمه فيه.","16:3":"لا تأكلوه مع خبز مختمر، بل كلوه مع فطير طوال سبعة أيام، لأن هذا هو خبز المشقة، إذ إنكم على عجل غادرتم ديار مصر، وبذلك تتذكرون يوم خروجكم من ديار مصر كل أيام حياتكم.","16:4":"لا تبقوا خميرا في أرضكم طوال سبعة أيام، ولا يبت شيء من لحم حمل الفصح المذبوح في مساء اليوم الأول إلى الغد.","16:5":"يحظر عليكم ذبح الفصح في أي من مدنكم التي يورثها لكم الرب إلهكم،","16:6":"بل في المكان الذي يختاره الرب إلهكم ليحل اسمه فيه تذبحون الفصح في المساء، عند غروب الشمس، في نفس ميعاد خروجكم من مصر.","16:7":"فتشوونه وتأكلونه في الموضع الذي يختاره الرب، ثم تنصرفون في الغد كل إلى خيمته.","16:8":"ستة أيام تأكلون فطيرا، وفي اليوم السابع تتوقفون عن كل عمل، وتحتفلون معتكفين للرب.","16:9":"احسبوا سبعة أسابيع منذ ابتداء حصاد الزرع،","16:10":"ثم احتفلوا بعيد الأسابيع للرب إلهكم، حيث تحضرون ما تسخو به نفوسكم حسب ما يبارككم الرب به،","16:11":"فتحتفلون أنتم وأبناؤكم وبناتكم وعبيدكم وإماؤكم، واللاويون المقيمون في مدنكم، والغريب واليتيم والأرملة الذين بينكم، لدى الرب في الموضع الذي يختاره ليحل اسمه فيه.","16:12":"وتذكروا أنكم كنتم عبيدا في مصر، فأطيعوا هذه الفرائض واعملوا بها.","16:13":"واحتفلوا بعيد المظلات في نهاية موسم الحصاد، عند جمع غلات بيادركم ومعاصركم،","16:14":"فتحتفلون بالعيد أنتم وأبناؤكم وبناتكم وإماؤكم واللاويون والغريب واليتيم والأرملة المقيمون في مدنكم،","16:15":"فتعيدون للرب سبعة أيام في الموضع الذي يختاره الرب، لأن الرب إلهكم يبارك لكم محاصيلكم وكل ما تنتجه أيديكم، فيكمل بذلك فرحكم.","16:16":"ويحضر جميع ذكوركم ثلاث مرات للمثول أمام الرب إلهكم في الموضع الذي يختاره الرب، وذلك في عيد الفطير وعيد الأسابيع وعيد المظال. وإياهم أن يمثلوا أمام الرب من غير تقدمات.","16:17":"فيقدم كل واحد ما تسخو به نفسه حسبما باركه الرب إلهه.","16:18":"وأقيموا لأنفسكم قضاة ومدبرين في جميع المدن التي يورثكم إياها الرب إلهكم بحسب أسباطكم فيقضوا بين الشعب بالعدل.","16:19":"لا تعوجوا القضاء ولا تحابوا، ولا تقبلوا رشوة، لأن الرشوة تعمي أبصار الحكماء، وتعوج أقوال الصديقين.","16:20":"العدل والعدل وحده أجروا، لتحيوا وتمتلكوا الأرض التي يهبها الرب إلهكم لكم.","16:21":"لا تنصبوا لأنفسكم سواري من شجر ما إلى جوار مذبح الرب إلهكم الذي تبنونه لكم،","16:22":"ولا تقيموا لكم أنصابا من حجارة لأن هذه مكروهة لدى الرب.","17:1":"لا تذبحوا للرب إلهكم ثورا أو حملا فيه عيب أو شيء رديء، لأن ذلك رجس لدى الرب.","17:2":"إذا ارتكب بينكم، رجل أو امرأة، مقيم في إحدى مدنكم التي يورثكم إياها الرب إلهكم، الشر في عيني الرب متعديا عهده،","17:3":"فغوى وعبد آلهة أخرى وسجد لها أو للشمس أو للقمر أو لأي من كواكب السماء مما حظرته عليكم،","17:4":"وشاع خبره، فسمعتم به، وتحققتم بعد فحص دقيق أن ذلك الرجس اقترف في إسرائيل،","17:5":"فأخرجوا ذلك الرجل أو تلك المرأة، الذي ارتكب ذلك الإثم إلى خارج المدينة، وارجموه بالحجارة حتى يموت.","17:6":"لا تقتله إلا بعد أن تقوم عليه شهادة اثنين أو ثلاثة ويحظر أن تقتل بموجب شهادة واحد فقط.","17:7":"ويكون الشهود هم أول من يرجمونه، ثم يتعاقب عليه الشعب. فتستأصلون عندئذ الشر من بينكم.","17:8":"إذا تعذر عليكم إصدار حكم في قضية سفك دم أو دعوى حق أو اعتداء بالضرب، مما يجري من أمور الخصومات في مدنكم، فقوموا وامضوا إلى المكان الذي يختاره الرب إلهكم،","17:9":"واحضروا أمام الكهنة اللاويين والقاضي القائم في تلك الأيام، واسألوا، فيخبروكم بحكم القضاء.","17:10":"فتنفذوا ما يصدرون من قرارات في الموضع الذي يختاره الرب. واحرصوا على العمل بمقتضى ما يعلمونكم","17:11":"واعملوا بموجب الشريعة التي يعلمونكم إياها، والقضاء الذي يصدرونه. ولا تحيدوا عما ينصون عليه من حكم لا يمينا ولا شمالا.","17:12":"ومن يرفض متمردا تنفيذ حكم الكاهن الماثل هناك لخدمة الرب إلهكم، أو القاضي، فإنه يقتل. وبذلك يستأصل الشر من إسرائيل.","17:13":"فيشيع الخبر بين جميع الشعب فيخافون ولا يتمردون بعد.","17:14":"ومتى بلغتم الأرض التي يورثها لكم الرب إلهكم وامتلكتموها واستوطنتم فيها وقلتم: لنتوج علينا ملكا كبقية الأمم المحيطة بنا","17:15":"فإنكم تقيمون عليكم ملكا الذي يختاره الرب إلهكم، شريطة أن يكون واحدا من أسباطكم. يحظر عليكم أن تقيموا ملكا أجنبيا لا ينتمي إلى أحد أسباطكم.","17:16":"ولكن إياه أن يكثر من عدد خيوله، أو يعيد الشعب إلى مصر ليحصل على مزيد من الخيل لأن الرب قال لكم: لا ترتدوا للرجوع في هذه الطريق أيضا.","17:17":"وليحذر من أن يكون مزواجا لئلا يزيغ قلبه، ولا يكثر لنفسه من الذهب والفضة.","17:18":"وحين يتبوأ عرش مملكته فلينسخ لنفسه هذه الشريعة في كتاب وينقلها عن الكهنة واللاويين،","17:19":"فتكون معه ليطالعها كل أيام حياته ليتعلم أن يتقي الرب إلهه ويطيع جميع كلمات هذه الشريعة وهذه الفرائض ليعمل بها،","17:20":"لئلا يتكبر على إخوته ويحيد عن الوصية يمينا أو شمالا. فإن فعل ذلك فإنه وذريته يملكون طويلا في وسط إسرائيل.","18:1":"لا يرث الكهنة اللاويون ولا أحد من سبط لاوي ملكا أو نصيبا مع بني إسرائيل. إنما يأكلون من محرقات الرب ونصيبه.","18:2":"لا يرثون مع إخوتهم، لأن الرب هو نصيبهم كما وعدهم.","18:3":"وهذا هو حق الكهنة من الذبائح التي يقربها الشعب بقرا كانت أم غنما: يقدم الشعب للكاهن الساعد والفكين والكرش،","18:4":"كما تعطونه أول حصاد حنطتكم وخمركم وزيتكم، وأول جزاز غنمكم،","18:5":"لأن الرب إلهكم اختاره من بين جميع أسباطكم ليقوم بالخدمة باسم الرب، هو وأبناؤه كل الأيام.","18:6":"وإذا أقبل لاوي من إحدى مدنكم من أي مكان في إسرائيل، حيث هو متغرب، ليمكث برغبة قلبية صادقة في الموضع الذي يختاره الرب،","18:7":"فإن من حقه أن يخدم باسم الرب إلهكم كبقية إخوته اللاويين الماثلين هناك أمام الرب.","18:8":"ومن حقه أيضا أن ينال نصيبا متساويا من التقدمات، علاوة عما يكون قد حصل عليه من بيع ما ورثه عن آبائه.","18:9":"ومتى دخلتم إلى الأرض التي يورثكم إياها الرب إلهكم، فلا تتعلموا ممارسة رجاسات تلك الأمم المقيمة هناك.","18:10":"ولا يكن بينكم من يجيز ابنه ولا ابنته في النار، ولا يتعاطى العرافة ولا العيافة ولا ممارسة الفأل أو السحر،","18:11":"ولا من يرقي رقية أو يشاور جانا أو وسيطا، أو يستحضر أرواح الموتى ليسائلهم،","18:12":"لأن كل من يتعاطى ذلك مكروه لدى الرب. فبسبب هذه الأرجاس عزم الرب إلهكم على طرد هذه الأمم من أمامكم،","18:13":"فكونوا كاملين لدى الرب إلهكم.","18:14":"إن تلك الأمم التي أنتم تستأصلونها تصدق ممارسة المشعوذين والعرافين، وأما أنتم فإن الرب إلهكم يحظر عليكم ذلك.","18:15":"سيقيم الرب فيكم نبيا مثلي من بني إسرائيل، له تسمعون،","18:16":"فقد استجاب الرب إلهكم ما طلبتم منه في حوريب في يوم الاجتماع عندما قلتم: لا نعود نسمع صوت الرب إلهنا، ولا نرى النار العظيمة أيضا لئلا نموت","18:17":"فقال لي الرب: لقد أصابوا في ما تكلموا.","18:18":"لهذا أقيم لهم نبيا من بين إخوتهم مثلك، وأضع كلامي في فمه، فيخاطبهم بكل ما آمره به.","18:19":"فيكون أن كل من يعصى كلامي الذي يتكلم به باسمي، فأنا أحاسبه.","18:20":"وأما النبي الذي يتجبر فينطق باسمي بما لم آمره أن يتكلم به، أو يتنبأ باسم آلهة أخرى، فإنه حتما يموت.","18:21":"وإن سألتم في أنفسكم: كيف نميز الكلام الذي لم يصدر عن الرب؟","18:22":"فإن كل ما يتنبأ به النبي باسم الرب ولا يتحقق يكون ادعاء منه لم ينطق به الرب، بل بطغيان تكلم به النبي فلا تخف منه.","19:1":"متى أفنى الرب إلهكم الأمم الذين سيورثكم أرضهم، وسكنتم في مدنهم وبيوتهم،","19:2":"فأفرزوا لأنفسكم ثلاث مدن في وسط أرضكم التي يهبها لكم الرب إلهكم لتمتلكوها.","19:3":"فعبدوا الطرق إليها، وقسموا الأرض التي يهبها الرب إلهكم لكم إلى ثلاث مناطق، لتكون ملجأ يلوذ بها كل من قتل نفسا عن غير عمد.","19:4":"وهذا هو الحكم المتعلق بالقاتل الذي يلجأ إلى هناك فيحيا: من ضرب صاحبه عن غير قصد، وهو لا يكن له البغضاء سابقا،","19:5":"ومن انطلق مع صاحبه إلى الغابة ليحتطب، فأفلتت حديدة الفأس من رأس الذراع الخشبية وأصابت صاحبه فمات، يلجأ القاتل إلى إحدى تلك المدن ويحيا","19:6":"لئلا يسعى طالب الثأر وراءه عند احتدام نقمته ويدركه إذا طالت الطريق ويقتله، مع أنه لا يستحق جزاء الموت، لأن القاتل لم يضمر البغضاء للمقتول من قبل","19:7":"لهذا أنا آمركم أن تفرزوا لأنفسكم ثلاث مدن.","19:8":"وإن وسع الرب إلهكم أرضكم، كما أقسم لآبائكم، وأورثكم جميع الأرض التي وعد أن يهبها لهم،","19:9":"وإذا أطعتم هذه الوصايا كلها وعملتم بها كما أوصيكم اليوم، وأحببتم الرب إلهكم وسلكتم في سبله دائما، فأضيفوا لأنفسكم مدن ملجإ أخرى","19:10":"فلا يسفك دم بريء في وسط أرضكم التي يهبها الرب إلهكم لكم ميراثا، فتكون ملطخة بالدم.","19:11":"ولكن إذا كمن إنسان يضمر البغضاء لصاحبه وقام عليه وضربه ضربة قاتلة أفضت إلى موته، ثم هرب إلى إحدى مدن الملجإ،","19:12":"يوجه شيوخ مدينته من يقبض عليه هناك، ويأتي به، فيسلمونه إلى طالب الثأر فيموت.","19:13":"لا تترَأف به قلوبكم، بل انتقموا لدم البريء في إسرائيل فيكون لكم خير.","19:14":"لا تنقلوا حدود أرض صاحبكم التي نصبها الأولون لتزيدوا من ميراثكم الذي يهبه لكم الرب إلهكم لتمتلكوه.","19:15":"لا يثبت على إنسان ذنب ما أو خطيئة ما من جميع الخطايا التي يرتكبها الإنسان على فم شاهد واحد، إنما بشهادة اثنين أو ثلاثة يثبت الذنب.","19:16":"إذا شهد واحد على آخر شهادة زور متهما إياه بارتكاب ذنب،","19:17":"يمثل الرجلان المتخاصمان في محضر الرب أمام الكهنة والقضاة المعينين في تلك الأيام.","19:18":"فإن تحقق القضاة بعد فحص دقيق أن الشاهد قد شهد زورا على أخيه،","19:19":"فأنزلوا به العقاب الذي كان سينزله بأخيه، فتستأصلوا الشر من بينكم،","19:20":"فيشيع الخبر ويسمع به بقية الشعب فيخافون، ولا يعودون يقدمون على مثل هذا الأمر القبيح في وسطكم.","19:21":"لا تترَأف به قلوبكم. حياة بحياة، وعين بعين، وسن بسن، ويد بيد، ورجل برجل.","20:1":"إذا ذهبتم لمحاربة عدوكم، ووجدتم أن عدوكم أكثر منكم عددا وخيلا ومركبات، فلا تخافوا منه، لأن الرب إلهكم الذي حرركم من ديار مصر يقف معكم.","20:2":"وعندما تكونون على وشك خوض المعركة يتقدم الكاهن ويخاطب الجيش:","20:3":"اسمع ياإسرائيل: أنتم اليوم موشكون على محاربة أعدائكم، فلا تهن قلوبكم، لا تخافوا منهم ولا ترتعدوا ولا ترهبوهم،","20:4":"لأن الرب إلهكم سائر معكم لمحاربة أعدائكم عنكم، وليخلصكم.","20:5":"ثم يقول القادة للجيش: هل بينكم من بنى بيتا جديدا ولم يدشنه بعد؟ فليرجع إلى بيته، لئلا يقتل في المعركة فيدشنه رجل آخر.","20:6":"هل بينكم من غرس كرما ولم يجن أول ثماره بعد؟ فليرجع إلى بيته لئلا يقتل في المعركة فيجني أول ثمار كرمه رجل آخر.","20:7":"هل بينكم رجل خطب امرأة ولم يتزوجها بعد؟ ليرجع إلى بيته لئلا يقتل في المعركة فيتزوجها رجل آخر.","20:8":"ثم يستطرد قادة الجيش قائلين: هل بينكم رجل خائف واهن القلب؟ ليرجع إلى بيته لئلا يعتري الخوف قلوب إخوته مثله.","20:9":"وعندما يفرغ القادة من مخاطبة الجيش، يعينون ضباطا على الجنود.","20:10":"وحين تتقدمون لمحاربة مدينة فادعوها للصلح أولا.","20:11":"فإن أجابتكم إلى الصلح واستسلمت لكم، فكل الشعب الساكن فيها يصبح عبيدا لكم.","20:12":"وإن أبت الصلح وحاربتكم فحاصروها","20:13":"فإذا أسقطها الرب إلهكم في أيديكم، فاقتلوا جميع ذكورها بحد السيف.","20:14":"وأما النساء والأطفال والبهائم، وكل ما في المدينة من أسلاب، فاغنموها لأنفسكم، وتمتعوا بغنائم أعدائكم التي وهبها الرب إلهكم لكم.","20:15":"هكذا تفعلون بكل المدن النائية عنكم التي ليست من مدن الأمم القاطنة هنا.","20:16":"أما مدن الشعوب التي يهبها الرب إلهكم لكم ميراثا فلا تستبقوا فيها نسمة حية،","20:17":"بل دمروها عن بكرة أبيها، كمدن الحثيين والأموريين والكنعانيين والفرزيين والحويين واليبوسيين كما أمركم الرب إلهكم،","20:18":"لكي لا يعلموكم رجاساتهم التي مارسوها في عبادة آلهتهم، فتغووا وراءهم وتخطئوا إلى الرب إلهكم.","20:19":"وإذا حاصرتم مدينة حقبة طويلة معلنين الحرب عليها لافتتاحها، فلا تقطعوا أشجارها بحد الفأس وتتلفوها لأنكم تأكلون من ثمارها. هل شجرة الحقل إنسان حتى يهرب أمامكم في الحصار؟","20:20":"أما الأشجار التي لا يؤكل ثمرها فأتلفوها واقطعوها، لاستخدامها في بناء حصون حول المدينة المحاصرة المتحاربة معكم، إلى أن يتم سقوطها.","21:1":"إذا وجدتم قتيلا ملقى في الحقل في الأرض التي يهبها الرب إلهكم لكم لامتلاكها، ولم يعرف قاتله.","21:2":"يقوم شيوخكم وقضاتكم بقياس المسافات الواقعة بين موضع جثة القتيل والمدن المجاورة.","21:3":"فيحضر شيوخ أقرب مدينة إلى الجثة، عجلة لم يوضع عليها محراث، ولم تجر بنير،","21:4":"ويأخذونها إلى واد فيه ماء دائم الجريان لم يحرث فيه ولم يزرع، فيكسرون عنق العجلة في الوادي.","21:5":"ثم يتقدم الكهنة بنو لاوي، لأن الرب إلهكم قد اختارهم لخدمته، ولإعلان البركة باسم الرب، وللقضاء في كل خصومة وكل ضربة.","21:6":"فيغسل جميع شيوخ تلك المدينة القريبة من الجثة أيديهم فوق العجلة المكسورة العنق في الوادي.","21:7":"ويقولون: أيدينا لم تسفك هذا الدم، وأعيننا لم تشهده.","21:8":"اغفر يارب لشعبك إسرائيل الذي افتديته، ولا تطالبنا بدم بريء سفك في وسط شعبك إسرائيل. فيصفح الرب عن سفك هذا الدم.","21:9":"وهكذا تبرأون من سفك الدم البريء في وسطكم، إذا صنعتم ما هو صالح في عيني الرب.","21:10":"إذا ذهبتم لمحاربة أعدائكم، وأظفركم الرب إلهكم بهم، وسبيتم منهم سبيا،","21:11":"وشاهد أحدكم بين الأسرى امرأة جميلة الصورة فأولع بها وتزوجها،","21:12":"فحين يدخلها إلى بيته يدعها تحلق رأسها وتقلم أظفارها،","21:13":"ثم ينزع ثياب سبيها عنها، ويتركها في بيته شهرا من الزمان تندب أباها وأمها، ثم بعد ذلك يعاشرها وتكون له زوجه.","21:14":"فإن لم ترقه بعد ذلك، فليطلقها لتذهب حيث تشاء. لا يبيعها بفضة أو يستعبدها، لأنه قد أذلها.","21:15":"إن كان رجل متزوجا من امرأتين، يؤثر إحداهما وينفر من الأخرى، فولدت كلتاهما له أبناء، وكان الابن البكر من إنجاب المكروهة،","21:16":"فحين يوزع ميراثه على أبنائه، لا يحل له أن يقدم ابن الزوجة الأثيرة ليجعله بكره في الميراث على بكره ابن الزوجة المكروهة.","21:17":"بل عليه أن يعترف ببكورية ابن المكروهة، ويعطيه نصيب اثنين من كل ما يملكه، لأنه هو أول مظهر قدرته، وله حق البكورية.","21:18":"إن كان لرجل ابن عنيد متمرد، لا يطيع أمر أبيه ولا قول أمه، ويؤدبانه ولكن من غير جدوى.","21:19":"فليقبض عليه والداه ويأتيا به إلى شيوخ مدينته في ساحة القضاء،","21:20":"ويقولان للشيوخ: ابننا هذا عنيد متمرد، لا يطيع قولنا، وهو مبذر سكير.","21:21":"فيرجمه رجال المدينة جميعهم بالحجارة حتى يموت. وهكذا تستأصلون الشر من بينكم ويشيع الخبر بين الشعب كله فيخاف.","21:22":"إن ارتكب إنسان جريمة عقابها الإعدام، ونفذ فيه القضاء وعلقتموه على خشبة،","21:23":"فلا تبت جثته على الخشبة، بل ادفنوه في نفس ذلك اليوم، لأن المعلق ملعون من الله. فلا تنجسوا أرضكم التي يهبها لكم الرب ميراثا.","22:1":"إن رأيت ثور جارك أو خروفه شاردا، فلا تتغاض عنه. بل أعده حتما إلى صاحبه.","22:2":"وإن لم يكن صاحبه مقيما قريبا منك، أو لم تعرفه، فاحتفظ به في بيتك حتى يطلبه صاحبه فترده إليه.","22:3":"وهكذا تفعل إذا عثرت على حمار جارك أو ثيابه، أو أي شيء مفقود تجده. لا يحل لك أن تتغاضى عنه.","22:4":"لا تتغافل عن إعانة جارك إذا رأيت حماره أو ثوره واقعا في الطريق بل هب لتعاونه ولتقيمه معه.","22:5":"يحظر على المرأة ارتداء ثياب الرجال، كما يحظر على الرجل ارتداء ثياب النساء، لأن كل من يفعل ذلك يصبح مكروها لدى الرب إلهكم.","22:6":"إن اتفق أن رأيت عش طائر على جانب الأرض أو على شجرة ما أو ملقى على الأرض فيه أم تحتضن فراخا، أو ترقد على بيض، فلا تأخذ الأم مع الأولاد.","22:7":"أطلق الأم وخذ الفراخ لنفسك، فيكون لك خير وتطيل أيام حياتك.","22:8":"إذا بنيت بيتا جديدا، فابن سياجا حول بيتك، لئلا يسقط منه أحد فتتحمل ذنب دمه.","22:9":"لا تزرع حقلك صنفين من البذور، لأنك إن فعلت يصبح محصول نوعي الزرع مقدسا من نصيب الكهنة.","22:10":"لا تحرث على ثور وحمار معا،","22:11":"ولا تلبس ثوبا مصنوعا من كتان وصوف معا.","22:12":"اصنعوا أهدابا مجدولة على أربعة أطراف الأثواب التي تتغطون بها.","22:13":"إذا تزوج رجل من فتاة، ثم بعد أن عاشرها أبغضها،","22:14":"واتهمها بما يشينها، وأشاع عنها ما يسيء إلى سمعتها قائلا: لقد تزوجت هذه المرأة، ولما عاشرتها، اكتشفت أنها لم تكن عذراء.","22:15":"يأخذها والداها إلى شيوخ المدينة المجتمعين في ساحة القضاء، ويعرضان دليل عذراويتها.","22:16":"ويقول والد الفتاة للشيوخ: لقد زوجت هذا الرجل من ابنتي فأبغضها.","22:17":"وها هو يروج عنها أخبارا قائلا: لم تكن ابنتك عذراء عندما عاشرتها. ولكن هذا هو دليل عذراوية ابنتي. ويبسطان الثوب أمام شيوخ المدينة.","22:18":"فيأخذ شيوخ تلك المدينة الرجل ويؤدبونه،","22:19":"ويفرضون عليه غرامة مقدارها مئة قطعة من الفضة، يعطونها لأبي الفتاة. لأنه أساء إلى سمعة عذراء من إسرائيل، فتكون له زوجة مدى حياته، لا يقدر أن يطلقها.","22:20":"ولكن إن ثبتت صحة التهمة، ولم تكن الفتاة عذراء حقا،","22:21":"يؤتى بالفتاة إلى باب بيت أبيها ويرجمها رجال مدينتها بالحجارة حتى تموت، لأنها ارتكبت قباحة في إسرائيل، وزنت في بيت أبيها. وبذلك تستأصلون الشر من بينكم.","22:22":"وإذا ضبطتم رجلا مضطجعا مع امرأة متزوجة تقتلونهما كليهما، فتنزعون الشر من وسطكم.","22:23":"وإذا التقى رجل بفتاة مخطوبة لرجل آخر في المدينة وضاجعها،","22:24":"فأخرجوهما كليهما إلى ساحة بوابة تلك المدينة، وارجموهما بالحجارة حتى يموتا، لأن الفتاة لم تستغث وهي في المدينة، والرجل لأنه اعتدى على خطيبة الرجل الآخر، فتستأصلون الشر من وسطكم.","22:25":"ولكن إن التقى ذلك الرجل بالفتاة المخطوبة في الحقل، وأمسكها وضاجعها، يرجم الرجل وحده ويموت،","22:26":"وأما الفتاة فلا ترجم، لأنها لم ترتكب خطيئة جزاؤها الموت، بل تكون كرجل هاجمه آخر وقتله،","22:27":"لأنه لابد أن تكون الفتاة المخطوبة قد استغاثت في الخلاء حيث وجدها الرجل، فلم يأت من ينقذها.","22:28":"وإذا وجد رجل فتاة عذراء غير مخطوبة فأمسكها وضاجعها وضبطا معا،","22:29":"يدفع الرجل الذي ضاجع الفتاة خمسين قطعة من الفضة ويتزوجها، لأنه قد اعتدى عليها. ولا يقدر أن يطلقها مدى حياته.","22:30":"لا يتزوج أحد أرملة أبيه لأن هذا عار وإهانة لأبيه.","23:1":"لا يدخل ذو الخصيتين المرضوضتين أو المجبوب في جماعة الرب.","23:2":"لا يدخل ابن زنى ولا أحد من ذريته حتى الجيل العاشر في جماعة الرب.","23:3":"لا يدخل عموني ولا موآبي في جماعة الرب، ولا أحد من ذريتهم حتى بعد الجيل العاشر في جماعة الرب وإلى الأبد،","23:4":"لأنهم لم يستقبلوكم بالخبز والماء في الطريق عند خروجكم من مصر، ولأنهم استأجروا بلعام بن بعور من فتور أرام النهرين ليلعنكم","23:5":"ولكن الرب إلهكم لم يشأ أن يستجيب لبلعام، بل حول لأجلكم اللعنة إلى بركة، لأن الرب إلهكم قد أحبكم.","23:6":"لا تسعوا في سبيل مسالمتهم وخيرهم إلى الأبد.","23:7":"لا تمقتوا الأدوميين لأنهم إخوتكم، ولا تكرهوا المصريين لأنكم كنتم ضيوفا في ديارهم","23:8":"ومن يولد من ذريتهم في الجيل الثالث يدخل في جماعة الرب.","23:9":"إذا خرجتم لمحاربة أعدائكم فامتنعوا عن كل شيء قبيح","23:10":"فإن كان بينكم رجل غير طاهر على أثر استحلام فليمض إلى خارج المعسكر. لا يدخل إليه.","23:11":"وعند حلول المساء يستحم بماء، ثم يدخل إلى المعسكر عند غروب الشمس.","23:12":"وعليكم أن تحددوا موضعا لقضاء الحاجة خارج المعسكر.","23:13":"وليكن مع كل واحد منكم وتد بين عتاده ليحفر به حفرة يقضي فيها حاجته، ثم يغطي برازه بالتراب،","23:14":"لأن الرب إلهكم سائر في وسط معسكركم لينقذكم ويظفركم بأعدائكم. فليكن معسكركم مقدسا لئلا يشهد فيه أقذارا فيتحول عنكم.","23:15":"إذا لجأ إليكم عبد هارب من مولاه، لا تسلموه إلى مولاه،","23:16":"بل يقيم حيث يطيب له في الموضع الذي يختاره في إحدى مدنكم ولا تظلموه.","23:17":"لا يكن من بنات إسرائيل ولا من أبناء إسرائيل زانيات ومأبونو معابد.","23:18":"لا تأتوا بتقدمة نذر ما إلى بيت الرب إلهكم من مكسب زانية أو مأبون، لأن كليهما رجس أمام الرب.","23:19":"لا تتقاضوا فوائد عما تقرضونه لإخوتكم من بني إسرائيل، سواء كانت القروض فضة أو أطعمة أو أي شيء آخر.","23:20":"أما الأجنبي فأقرضوه بربا. إنما إياكم إقراض أخيكم بفائدة، ليبارككم الرب إلهكم في كل ما تنتجه أيديكم في الأرض التي أنتم ماضون لامتلاكها.","23:21":"إذا نذرتم نذرا للرب فلا تماطلوا في الوفاء به، لأن إلهكم يطالبكم به ويحسب ذلك عليكم ذنبا","23:22":"وإن لم تنذروا لا تكون عليكم خطيئة.","23:23":"أما ما تعهدت به شفتاك فذاك احفظه وأوفه، كما نذرت طواعية للرب إلهك، وكما تعهد به فمك.","23:24":"إذا دخلت كرم عنب جارك فكل منه بقدر ما تشتهي نفسك حتى الشبع، ولكن لا تقطف من عنبه وتضعه في وعائك.","23:25":"إذا دخلت حقل قمح صاحبك فاقطف من سنابله، ولكن لا تحصد منه بمنجلك.","24:1":"إذا تزوج رجل من فتاة ولم ترق له بعد ذلك لأنه اكتشف فيها عيبا ما، وأعطاها كتاب طلاق وصرفها من بيته،","24:2":"فتزوجت من رجل آخر بعد أن أصبحت طليقة،","24:3":"ثم كرهها الزوج الثاني وسلمها كتاب طلاق وصرفها من بيته، أو إذا مات هذا الزوج،","24:4":"فإنه يحظر على زوجها الأول الذي طلقها أن يتزوجها مرة أخرى، بعد أن تنجست. لأن ذلك رجس لدى الرب. فلا تجلبوا خطيئة على الأرض التي يهبها الرب إلهكم لكم ميراثا.","24:5":"إذا تزوج رجل حديثا يعفى من الجندية والمسئوليات العسكرية لمدة سنة، يقضيها حرا في بيته ليسعد زوجته ويسرها.","24:6":"لا يسترهن أحد رحى أو أحد حجريها، لأنه يسترهن مصدر الرزق.","24:7":"إذا خطف رجل أحدا من بني إسرائيل إخوته واسترقه وباعه، يموت الخاطف. فتجتثون الشر من بينكم.","24:8":"احرصوا على طاعة تعليمات الكهنة واللاويين في حالة الإصابة بالبرص، ونفذوا بدقة ما أمرتهم به.","24:9":"اذكروا ما عاقب الرب إلهكم به مريم في الطريق لدى خروجكم من ديار مصر.","24:10":"إذا أقرضت جارك قرضا فلا تدخل بيته لتسترهن منه شيئا،","24:11":"بل تمكث خارجا، فيأتي الرجل الذي تقرضه بالرهن إليك حيث تقف.","24:12":"وإن كان المقترض فقيرا فلا يبت رهنه عندك،","24:13":"بل رده إليه عند غروب الشمس لينام في ثوبه ويباركك، فيحسب الرب إلهك ذلك لك برا.","24:14":"لا تظلم أجيرا وفقيرا، سواء كان من بني إسرائيل أو من الغرباء المقيمين في مدينتك.","24:15":"ادفع له أجرته في يومه قبل غروب الشمس لأنه فقير، أجهد نفسه للحصول عليها. وإلا توجه إلى الرب بالشكوى ضدك، فتكون هذه عليك خطيئة.","24:16":"لا يقتل الآباء عوضا عن الأبناء، ولا يقتل الأبناء بدلا من الآباء، فكل إنسان يتحمل وزر نفسه.","24:17":"لا تحرفوا حكم العدالة فتظلموا الغريب واليتيم، ولا تسترهنوا ثوب الأرملة،","24:18":"واذكروا أنكم كنتم عبيدا في ديار مصر فأنقذكم الرب إلهكم. لهذا أوصيكم بالعدل.","24:19":"إذا حصدتم غلاتكم ونسيتم حزمة في الحقل فلا ترجعوا لأخذها، بل اتركوها للغريب واليتيم والأرملة، ليبارككم الرب إلهكم في كل ما تعمله أيديكم.","24:20":"إذا هززتم أشجار زيتونكم لإسقاط ثمارها، فلا تلتقطوا ما بقي في الأغصان منها، بل اتركوها وراءكم للغريب واليتيم والأرملة.","24:21":"إذا قطفتم كرومكم فلا تعاودوا قطف ما بقي من عناقيد وراءكم، بل اتركوها للغريب واليتيم والأرملة.","24:22":"واذكروا أنكم كنتم عبيدا في ديار مصر. من أجل هذا أوصيكم أن تنفذوا هذا الأمر.","25:1":"إذا نشبت خصومة بين قوم ورفعوا دعواهم إلى القضاء ليحكم القضاة بينهم، فليبرئوا البريء ويحكموا على المذنب.","25:2":"فإن كان المذنب مستوجب عقاب الجلد، يطرحه القاضي، ويجلدونه أمامه بعدد الجلدات التي يستحقها ذنبه،","25:3":"على ألا يزيد عدد الجلدات عن أربعين جلدة، لئلا يصبح المعاقب محتقرا.","25:4":"لا تكموا فم الثور الدارس للغلال.","25:5":"إذا سكن إخوة معا ومات أحدهم من غير أن ينجب ابنا، فلا يجب أن تتزوج امرأته رجلا من غير أفراد عائلة زوجها. بل ليتزوجها أخو زوجها ويعاشرها، وليقم نحوها بواجب أخي الزوج،","25:6":"ويحمل البكر الذي تنجبه اسم الأخ الميت، فلا ينقرض اسمه من أرض إسرائيل.","25:7":"وإن أبى الرجل أن يتزوج امرأة أخيه، تمضي المرأة إلى بوابة شيوخ المدينة وتقول: قد رفض أخو زوجي أن يخلد اسما لأخيه في إسرائيل، ولم يشأ أن يقوم نحوي بواجب أخي الزوج.","25:8":"فيدعوه شيوخ المدينة ويتداولون معه في الأمر. فإن أصر على الرفض وقال: لا أرضى أن أتزوجها.","25:9":"تتقدم امرأة أخيه إليه على مرأى من الشيوخ، وتخلع حذاءه من رجليه وتتفل في وجهه قائلة: هذا ما يحدث لمن يأبى أن يبني بيت أخيه.","25:10":"فيدعى في إسرائيل بيت مخلوع النعل.","25:11":"إذا تعارك رجلان فتدخلت زوجة أحدهما لتنقذ زوجها من قبضة يد ضاربه ومدت يدها وأمسكت بخصيته،","25:12":"فاقطعوا يدها ولا تشفقوا عليها.","25:13":"لا تحتفظ في كيسك بمعيارين مختلفين كبير وصغير،","25:14":"ولا يكن لك في بيتك مكيالان مختلفان كبير وصغير،","25:15":"بل لتكن أوزانك ومكاييلك صحيحة لا غش فيها، لتطول أيامك على الأرض التي يهبها لك الرب إلهك،","25:16":"لأن كل من غش في المكاييل أو الأوزان يصبح مكروها لدى الرب إلهكم.","25:17":"تذكروا ما صنعه بكم شعب عماليق لدى خروجكم من مصر،","25:18":"كيف تعرضوا لكم في الطريق وقضوا على المستضعفين المرتحلين في مؤخرة الشعب وأنتم مرهقون تعابى، ولم يخافوا الله .","25:19":"فمتى أراحكم الرب إلهكم من جميع أعدائكم المحيطين بكم في الأرض التي يهبها لكم ميراثا، امحوا ذكر شعب عماليق من تحت السماء. لا تنسوا هذا.","26:1":"ومتى بلغتم الأرض التي يهبها الرب إلهكم لكم ميراثا وامتلكتموها واستوطنتم فيها،","26:2":"فاجمعوا من أول كل ثمر تغله أرضكم التي يهبها الرب إلهكم لكم، وضعوه في سلال، وامضوا إلى الموضع الذي يختاره الرب إلهكم ليحل فيه اسمه.","26:3":"ويأتي صاحب التقدمة إلى الكاهن المعين ويقول: أعترف اليوم للرب إلهك أني قد جئت إلى الأرض التي حلف الرب لآبائنا أن يهبها لنا.","26:4":"فيتناول الكاهن السلة من يده ويضعها أمام مذبح الرب إلهكم،","26:5":"ثم يعلن صاحب التقدمة قائلا أمام الرب إلهكم: كان أبي أراميا تائها، ثم انحدر إلى مصر وتغرب هناك، ومعه نفر قليل. ولكنه أصبح هناك أمة كبيرة عظيمة.","26:6":"فأساء إلينا المصريون وأرهقونا وقسوا علينا في استعبادهم،","26:7":"فصرخنا إلى الرب إله آبائنا، فاستجاب لنا ورأى بؤسنا وتعبنا وضيقنا،","26:8":"فأخرجنا من ديار مصر بقوة شديدة وقدرة فائقة، وويلات عظيمة وآيات وعجائب،","26:9":"وأدخلنا إلى هذا المكان، ووهبنا هذه الأرض التي تفيض لبنا وعسلا.","26:10":"فها أنا الآن قد أتيت بأول ثمر الأرض التي وهبتني يارب ثم يضعه أمام الرب إلهكم ويسجد في حضرته،","26:11":"ويحتفل بجميع الخير الذي أنعم به الرب إلهكم عليه وعلى أهل بيته، هو واللاوي والغريب المقيم بينكم.","26:12":"ومتى انتهيت من تقديم كل عشور غلاتك في السنة الثالثة، سنة العشور، وأعطيت اللاوي والغريب واليتيم والأرملة فأكلوا في مدينتك وشبعوا،","26:13":"تقول في حضرة الرب إلهك: قد افرزت من بيتي العشور المقدسة وأعطيتها للاوي والغريب واليتيم والأرملة، طاعة لوصيتك التي أمرتني بها، فلم أتجاوز وصاياك ولا نسيتها.","26:14":"لم أتناول منه في أثناء حزني، ولم آخذ منه وأنا في حالة نجاسة، ولا أعطيت منه لأجل ميت. بل أطعت صوت إلهي وعملت بموجب كل ما أوصيتني به.","26:15":"أشرف يارب من مسكنك المقدس في السماء، وبارك شعبك إسرائيل، والأرض التي تفيض لبنا وعسلا، التي وهبتها لنا كما حلفت لآبائنا.","26:16":"لقد أمركم الرب إلهكم في هذا اليوم أن تمارسوا هذه الفرائض والأحكام، فأطيعوا، واعملوا بها من كل قلوبكم ومن كل نفوسكم،","26:17":"فأنتم قد أعلنتم اليوم أن الرب إلهكم وأنكم ستسلكون في سبله وتطيعون فرائضه وأحكامه وتسمعون لصوته","26:18":"كما أعلن الرب اليوم أنكم تكونون له شعبا خاصا، حسب وعده لكم، وأن عليكم طاعة وصاياه جميعها،","26:19":"فيجعلكم أسمى من كل الأمم التي خلقها من حيث الثناء والشرف والمجد، وتكونون شعبا مقدسا للرب إلهكم كما وعد».","27:1":"وأوصى موسى وشيوخ إسرائيل الشعب قائلين:«أطيعوا جميع الوصايا التي أنا آمركم بها اليوم.","27:2":"فعندما تجتازون نهر الأردن إلى الأرض التي يهبها الرب إلهكم لكم، تنصبون لأنفسكم حجارة كبيرة وتطلونها بالكلس،","27:3":"وتكتبون عليها جميع كلمات هذه الشريعة لدى عبوركم الأردن لدخول الأرض التي تفيض لبنا وعسلا، التي يهبها الرب إلهكم لكم، كما وعدكم الرب إله آبائكم.","27:4":"وما إن تعبروا نهر الأردن حتى تنصبوا هذه الحجارة التي أنا أوصيكم بها اليوم على جبل عيبال وتطلوها بالكلس.","27:5":"وتبنون هناك مذبحا للرب إلهكم، من حجارة غير منحوتة بحديد،","27:6":"بل من حجارة الحقل الخشنة لتقدموا عليها محرقات للرب إلهكم.","27:7":"وهناك تقربون ذبائح سلام، وتأكلون وتحتفلون في حضرة الرب إلهكم.","27:8":"وتنقشون على الحجارة نقشا دقيقا كلمات هذه الشريعة جميعها».","27:9":"ثم قال موسى والكهنة واللاويون لجميع شعب إسرائيل: «أنصتوا واصغوا يابني إسرائيل، اليوم أصبحتم شعبا للرب إلهكم.","27:10":"فاسمعوا لصوت الرب إلهكم وطبقوا وصاياه وفرائضه التي أنا آمركم اليوم بها».","27:11":"وأوصى موسى الشعب في ذلك اليوم نفسه قائلا:","27:12":"«هذه هي الأسباط التي تقف على جبل جرزيم ليباركوا الشعب بعد عبوركم نهر الأردن: أسباط شمعون ولاوي ويهوذا ويساكر ويوسف وبنيامين.","27:13":"أما الأسباط التي تقف على جبل عيبال لإعلان اللعنة فهي أسباط رأوبين وجاد وأشير وزبولون ودان ونفتالي.","27:14":"فيقول اللاويون بصوت عال لجميع شعب إسرائيل:","27:15":"ملعون الإنسان الذي يصنع تمثالا منحوتا أو مسبوكا مما تصنعه يدا نحات، وتنصبه للعبادة في الخفاء، لأن ذلك رجس لدى الرب. ويجيب جميع الشعب قائلين: آمين.","27:16":"ملعون كل من يستخف بأبيه وأمه. ويقول جميع الشعب: آمين.","27:17":"ملعون كل من يعبث بحدود أرض جاره. ويقول جميع الشعب: آمين.","27:18":"ملعون كل من يضل الكفيف عن طريقه. ويقول جميع الشعب: آمين.","27:19":"ملعون كل من يجور على حق الغريب واليتيم والأرملة. ويقول جميع الشعب: آمين.","27:20":"ملعون كل من يضاجع امرأة أبيه، لأنه يكشف ستر أبيه. ويقول جميع الشعب: آمين.","27:21":"ملعون كل من يضاجع بهيمة ما. ويقول جميع الشعب: آمين.","27:22":"ملعون كل من يضاجع أخته ابنة أمه أو ابنة أبيه. ويقول جميع الشعب: آمين.","27:23":"ملعون كل من يضاجع حماته. فيقول جميع الشعب: آمين.","27:24":"ملعون كل من يقتل صاحبه في الخفاء. فيقول جميع الشعب: آمين.","27:25":"ملعون كل من يأخذ رشوة ليقتل نفسا بريئة. فيقول جميع الشعب: آمين.","27:26":"ملعون كل من لا يطيع كلمات هذه الشريعة ولا يعمل بها. فيقول جميع الشعب: آمين.","28:1":"وإن أطعتم صوت الرب طاعة تامة، حرصا منكم على تنفيذ جميع وصاياه التي أوصيكم بها اليوم، فإن الرب إلهكم يجعلكم أسمى من جميع أمم الأرض.","28:2":"وإذا سمعتم لصوت الرب إلهكم فإن جميع هذه البركات تنسكب عليكم وتلازمكم.","28:3":"تكونون مباركين في المدينة ومباركين في الحقول.","28:4":"كما تتبارك ذريتكم، وغلات أرضكم، ونتاج بهائمكم وبقركم ونعاجكم.","28:5":"وتتبارك أيضا فواكه سلالكم وخبز معاجنكم.","28:6":"وتكونون مباركين في دخولكم وخروجكم","28:7":"ويهزم الرب أمامكم أعداءكم القائمين عليكم، فيقبلون عليكم في طريق واحدة، ولكنهم يولون الأدبار أمامكم في سبع طرق.","28:8":"يأمر الرب لكم بالبركة، فتمتليء خزائنكم. ويبارك كل ما تنتجه أيديكم وغلات أرضكم التي يهبها لكم.","28:9":"وإذا حفظتم وصاياه وسلكتم في سبله فإنه يجعلكم لنفسه شعبا مقدسا كما حلف لكم،","28:10":"فتدرك جميع شعوب الأرض أن اسم الرب قد حل عليكم، ويخافونكم.","28:11":"ويزيدكم الرب وفرة فيكثر من أبنائكم ونتاج بهائمكم ومن غلات أرضكم التي حلف لآبائكم أن يهبها لكم.","28:12":"ويفتح لكم الرب كنوز سمائه الصالحة، فيمطر على أرضكم في مواسمها، ويبارك كل ما تنتجه أيديكم، فتقرضون أمما كثيرة وأنتم لا تقترضون.","28:13":"وإذا أطعتم وصايا الرب التي أنا آمركم بها اليوم لتحفظوها وتعملوا بها، فإنه يجعلكم رؤوسا لا أذنابا، متسامين دائما، ولا يدرككم انحطاط أبدا.","28:14":"لا تنحرفوا يمينا أو شمالا عن جميع هذه الشرائع التي أنا أوصيكم بها اليوم، لكي لا تغووا وراء آلهة أخرى لتعبدوها.","28:15":"ولكن إن عصيتم صوت الرب إلهكم ولم تحرصوا على العمل بجميع وصاياه وفرائضه التي أنا آمركم اليوم بها، فإن جميع هذه اللعنات تحل بكم وتلازمكم.","28:16":"تكونون ملعونين في المدينة وملعونين في الحقول.","28:17":"وتكون سلالكم ومعاجنكم ملعونة.","28:18":"وتحل اللعنة بأبنائكم وغلات أرضكم ونتاج بقركم ونعاجكم،","28:19":"وتكونون ملعونين في ذهابكم وإيابكم،","28:20":"ويصب الرب عليكم اللعنة والفوضى والفشل في كل ما تنتجه أيديكم، حتى تهلكوا وتفنوا سريعا لسوء أفعالكم، إذ تركتموني.","28:21":"ويتفشى بينكم الوباء حتى يبيدكم عن الأرض التي أنتم ماضون إليها لامتلاكها،","28:22":"ويضربكم الرب بالسل والحمى والرعشة والالتهاب والجفاف واللفح والذبول، فتلازمكم حتى تفنوا.","28:23":"وتصبح السماء التي فوقكم كالنحاس والأرض تحتكم كالحديد.","28:24":"ويحول الرب مطر أرضكم إلى غبار وعواصف ترابية تنهمر عليكم من السماء حتى تهلكوا.","28:25":"ويهزمكم الرب أمام أعدائكم فتقبلون عليهم في طريق واحدة وتولون الأدبار أمامهم متفرقين في سبع طرق، وتصبحون عبرة لجميع ممالك الأرض.","28:26":"وتكون جثثكم طعاما لجميع طيور السماء ووحوش الأرض ولا يطردها أحد.","28:27":"ويصيبكم الرب بداء قرحة مصر وبالبواسير والجرب والحكة، ولا تجدون لها علاجا.","28:28":"ويبتليكم الرب بالجنون والعمى وارتباك الفكر،","28:29":"فتتحسسون طرقكم في الظهر كما يتحسس الأعمى طريقه في الظلام، وتبوء طرقكم بالإخفاق، ولا تكونون إلا مظلومين مغصوبين كل الأيام، وليس من منقذ.","28:30":"يخطب أحدكم امرأة ولكن آخر يتزوجها ويضاجعها. تبني بيتا ولا تسكن فيه، وتغرس كرما ولا تجنيه.","28:31":"يذبح ثورك أمام عينيك ولا تأكل منه، ويغتصب حمارك على مرأى منك ولا يرد إليك، ويستولي أعداؤك على ماشيتك وليس من منقذ.","28:32":"يساق أولادك وبناتك إلى أمة أخرى وعيناك تراقبانهم طوال النهار، حتى تكلا، وما في يدك حيلة.","28:33":"محصول أرضك وثمر تعبك يأكله شعب غريب عنك، ولا تكون سوى مظلوم مسحوق دائما.","28:34":"ويصيبك الجنون من هول ما ترى.","28:35":"ويبتليك الرب بقروح خبيثة تغطي الركبتين والساقين، حتى لا تجد لها شفاء من قمة الرأس إلى أخمص القدم.","28:36":"ينفيكم الرب أنتم وملككم الذي تختارونه إلى أمة لا تعرفونها أنتم ولا آباؤكم، حيث تعبدون هناك آلهة أخرى من خشب وحجر،","28:37":"وتصبحون مثار دهشة وسخرية وعبرة في نظر جميع الشعوب التي ينفيكم الرب إليهم","28:38":"تبذرون كثيرا من البذار في الحقول، ولا تحصدون إلا القليل، لأن الجراد يلتهمه.","28:39":"تكدحون في غرس كروم ومن خمرها لا تشربون، ومن ثمرها لا تجنون، لأن الدود ينخرها.","28:40":"تكتظ أراضيكم بأشجار الزيتون، ولكن من زيتها لا تدهنون، لأن زيتونكم ينتثر على الأرض قبل نضجه.","28:41":"تنجبون بنين وبنات ولا يكونون لكم، لأنهم يسبون.","28:42":"تلتهم أسراب الجراد أشجاركم وغلات أرضكم.","28:43":"يعظم شأن الغرباء المقيمين بينكم، ويتفاقم انحطاط شأنكم.","28:44":"هم يقرضونكم وأنتم لا تقرضونهم، وهم يكونون رأسا وأنتم تكونون ذنبا،","28:45":"وتحل بكم هذه اللعنات وتلازمكم وتلاحقكم حتى تهلكوا، لأنكم لم تطيعوا صوت الرب إلهكم لتحفظوا وصاياه وفرائضه التي أمركم بها،","28:46":"فتكون فيكم وفي ذريتكم عبرة ونذيرا إلى الأبد.","28:47":"ولأنكم لم تعبدوا الرب إلهكم بفرح وغبطة في زمن الازدهار والوفرة،","28:48":"فإنكم تصبحون عبيدا لأعدائكم الذين يرسلهم الرب عليكم في أحوال الجوع والعطش والعري والفاقة، ويضع نير حديد على أعناقكم حتى يهلككم.","28:49":"ويجلب الرب عليكم من بعيد، من أقصى الأرض، أمة لا تفهمون لغتها، فتنقض عليكم كالنسر.","28:50":"أمة يثير منظرها الرعب، لا تهاب الشيخ ولا ترأف بالطفل،","28:51":"فتستولي على نتاج بهائمكم، وتلتهم غلات أرضكم حتى تفنوا، ولا تبقي لكم قمحا ولا خمرا ولا زيتا ولا نتاج بقركم ونعاجكم حتى تهلككم.","28:52":"وتحاصركم في جميع مدنكم حتى تتهدم أسواركم الشامخة الحصينة التي وثقتم بمناعتها في كل مدنكم. فتحاصركم في جميع مدنكم في كل أرضكم التي يهبها الرب إلهكم لكم.","28:53":"فتأكلون في أثناء الحصار والضيقة التي يضايقكم بها عدوكم ثمار بطونكم، لحم أبنائكم وبناتكم الذين رزقكم بهم الرب إلهكم.","28:54":"فيقسو قلب أكثركم رقة ورأفة على أخيه وامرأته التي في حضنه وسائر أبنائه الأحياء.","28:55":"فلا يعطي أحدهم من لحم أبنائه، الذي يأكله، لأنه لم يبق لديه شيء سواه في الحصار والضيقة التي يضايقكم بها عدوكم في جميع مدنكم.","28:56":"وكذلك فإن أكثر النساء رقة ورأفة، والتي لنعومتها وترفهها لا تجرؤ على لمس الأرض بباطن قدمها، تبخل على زوجها رجل حضنها وعلى ابنها وابنتها","28:57":"بمشيمتها الساقطة منها، وبأولادها الذين تلدهم، لأنها تنوي أن تأكلهم سرا في أثناء الحصار، في الضيقة التي يضايقكم بها عدوكم في كل مدنكم.","28:58":"فإن لم تحرصوا على العمل بجميع كلمات هذه الشريعة المكتوبة في هذا الكتاب، لتهابوا اسم الرب إلهكم الجليل المرهوب،","28:59":"فإن الرب يجعل الضربات النازلة بكم وبذريتكم ضربات مخيفة وكوارث رهيبة دائمة وأمراضا خبيثة مزمنة،","28:60":"ويرسل عليكم كل أمراض مصر التي فزعتم منها فتلازمكم،","28:61":"ويسلط الرب عليكم أيضا كل داء وكل بلية لم ترد في كتاب الشريعة هذا، حتى تهلكوا.","28:62":"فتصيرون قلة بعد أن كنتم في كثرة نجوم السماء، لأنكم لم تسمعوا صوت الرب إلهكم.","28:63":"وكما سر الرب بكم فأحسن إليكم وكثركم، فإنه سيسر بأن يفنيكم ويهلككم فتنقرضون من الأرض التي أنتم ماضون إليها لامتلاكها.","28:64":"ويشتتكم الرب بين جميع الأمم من أقصى الأرض إلى أقصاها، فتعبدون هناك آلهة أخرى من خشب أو حجر لم تعرفوها أنتم ولا آباؤكم،","28:65":"ولا تجدون بين تلك الأمم اطمئنانا ولا مقرا لقدم، بل يعطيكم الرب قلبا هلعا، وعيونا أوهنها الترقب، ونفوسا يائسة.","28:66":"وتعيشون حياة مفعمة دائما بالتوتر، مليئة بالرعب ليلا ونهارا.","28:67":"وتقولون في الصباح: يا ليته المساء، وفي المساء: يا ليته الصباح، من فرط ارتعاب قلوبكم وما تشهده عيونكم من هول.","28:68":"ويردكم الرب إلى ديار مصر في سفن في طريق وعدكم ألا تعودوا ترونها، فتباعون هناك لأعدائكم عبيدا وإماء، وليس من يشتري».","29:1":"وهذه هي نصوص العهد الذي أمر الرب موسى بأن يبرمه مع بني إسرائيل في سهول موآب، فضلا عن العهد الذي قطعه معهم في حوريب.","29:2":"استدعى موسى جميع الإسرائيليين وقال لهم: «لقد شاهدتم بأعينكم ما أجراه الرب في ديار مصر بفرعون وسائر عبيده وبكل أرضه.","29:3":"بأعينكم أبصرتم تلك التجارب الهائلة والآيات والعجائب العظيمة.","29:4":"ولكن الرب لم يعطكم حتى الآن قلوبا لتعوا وعيونا لتبصروا وآذانا لتسمعوا.","29:5":"لقد قدتكم في البرية أربعين سنة، لم تبل فيها ثيابكم عليكم، ولم تهتريء نعالكم على أرجلكم.","29:6":"لم تأكلوا في خلالها خبزا ولم تشربوا خمرا أو مسكرا لكني أشبعتكم بما وفرته لكم من طعام وماء، لكي تعلموا أني أنا الرب إلهكم.","29:7":"وعندما بلغتم هذا الموضع تأهب سيحون ملك حشبون وعوج ملك باشان لحربنا، فدحرناهما","29:8":"واستولينا على أرضهما، وقسمناها على سبطي رأوبين وجاد ونصف سبط منسى.","29:9":"فأطيعوا نصوص هذا العهد واعملوا بها، لتفلحوا في كل ما تصنعونه.","29:10":"أنتم ماثلون اليوم جميعكم في حضرة الرب إلهكم: رؤساؤكم وقادة أسباطكم وعرفاؤكم وسائر رجال إسرائيل،","29:11":"وأطفالكم ونساؤكم، والغرباء المقيمون فى وسطكم، ممن يحتطب لكم ويستقي لكم ماءكم،","29:12":"لتدخلوا في عهد الرب إلهكم وقسمه الذي يبرمه الرب معكم اليوم،","29:13":"وليثبتكم اليوم لنفسه شعبا، فيكون لكم إلها كما وعدكم وكما حلف لآبائكم إبراهيم وإسحق ويعقوب.","29:14":"ولست أقطع هذا العهد وهذا القسم معكم وحدكم،","29:15":"بل فضلا عنكم أنتم الماثلين اليوم أمام الرب إلهنا، فإنني أبرمه أيضا مع الأجيال القادمة.","29:16":"لأنكم قد عرفتم كيف أقمنا في ديار مصر، وكيف جزنا فيما بين الأمم الذين عبرتم بهم،","29:17":"وشهدتم أرجاسهم وما لديهم من أصنام مصنوعة من خشب وحجر وفضة وذهب،","29:18":"لئلا يكون بينكم رجل أو امرأة أو عشيرة أو سبط مال قلبه عن الرب إلهنا، فغوى ليعبد آلهة تلك الأمم. فاحرصوا ألا يكون بينكم من تأصل فيه الشر، فيحمل ثمرا علقما ساما.","29:19":"فإن سمع كلام هذا القسم يستمطر بركة على نفسه قائلا: «سأكون آمنا حتى ولو أصررت على الاستمرار فى سلوك طريقي إن هذا يفضي إلى فناء الأخضر واليابس على حد سواء.","29:20":"إن الرب لا يشاء الرفق بمثل هذا الإنسان، بل يحتدم غضبه وغيرته عليه، فتنزل به كل اللعنات المدونة في هذا الكتاب، ويمحو اسمه من تحت السماء.","29:21":"ويفرزه الرب من بين أسباط إسرائيل ليهلكه بمقتضى جميع لعنات العهد المدونة في كتاب الشريعة هذا.","29:22":"فيشاهد أبناؤكم من الأجيال القادمة، والغرباء الوافدون من أرض بعيدة بلايا تلك الأرض وما يصيبها الرب به من أمراض،","29:23":"إذ تصبح جميع الأرض كبريتا، محترقة لا زرع فيها ولا نبات ولا عشب، وكأنها انقلبت كما جرى لسدوم وعمورة وأدمة وصبوييم، التي قلبها الرب من جراء غضبه وسخطه.","29:24":"فتقول جميع الأمم: لماذا فعل الرب هذا كله بهذه الأرض؟ ولماذا احتدام هذا الغضب العظيم؟","29:25":"فيكون الجواب: لأن هذا الشعب نقض عهد الرب إله آبائهم الذي قطعه معهم حين أخرجهم من ديار مصر،","29:26":"وغووا وعبدوا آلهة أخرى وسجدوا لها، آلهة غريبة لم يعرفوها ولم يعطها الرب لهم،","29:27":"فالتهب غضب الرب على تلك الأرض، فصب عليها كل اللعنات المدونة فى هذا الكتاب","29:28":"واجتثهم من أرضهم بغضب وسخط وغيظ عظيم، وطوح بهم إلى أرض أخرى كما هو حادث اليوم.","29:29":"إن السرائر للرب إلهنا، أما الوصايا المعلنة فهي لنا ولأبنائنا إلى الأبد، لنعمل بجميع كلمات هذه الشريعة.","30:1":"وعندما تحل بكم هذه البركات واللعنات كلها التي وضعتها أمامكم، ورددتموها في قلوبكم بين الأمم حيث شتتكم الرب إلهكم،","30:2":"ورجعتم إلى الرب إلهكم أنتم وبنوكم، وسمعتم لصوته من كل قلوبكم ونفوسكم بحسب كل ما أنا أوصيكم به اليوم،","30:3":"فإن الرب إلهكم يرد سبيكم ويرحمكم، ويلم شتاتكم من بين جميع الشعوب الذين نفاكم الرب إلهكم إليهم.","30:4":"فإن كان قد بددكم إلى أقصى السماوات فمن هناك يجمعكم ويرجع بكم،","30:5":"ويعيدكم إلى الأرض التي ورثها آباؤكم فتمتلكونها، ويحسن إليكم ويكثركم أكثر من آبائكم.","30:6":"ويطهر الرب إلهكم قلوبكم وقلوب نسلكم لتحبوا الرب إلهكم من كل قلوبكم ومن كل نفوسكم لتحيوا مطمئنين","30:7":"ويحول الرب إلهكم كل هذه اللعنات لتنصب على أعدائكم وعلى مبغضيكم الذين طردوكم،","30:8":"وأما أنتم فتطيعون صوت الرب من جديد وتعملون بجميع وصاياه التي أنا أوصيكم بها الآن.","30:9":"فيفيض الرب عليكم خيرا في كل ما تنتجه أيديكم ويكثر ثمرة أحشائكم ونتاج بهائمكم، وغلات أرضكم، لأن الرب يعود فيبتهج بكم ويجعلكم مزدهرين، كما ابتهج بآبائكم.","30:10":"هذا إن سمعتم لصوت الرب إلهكم وحفظتم وصاياه وفرائضه المدونة في كتاب الشريعة هذا، وإن رجعتم إلى الرب إلهكم من كل قلوبكم ومن كل نفوسكم.","30:11":"إن ما أوصيكم به اليوم من وصايا ليست متعذرة عليكم ولا بعيدة المنال،","30:12":"فهي ليست في السماء حتى تقولوا: من يصعد لأجلنا إلى السماء ليأتي لنا بها ويتلوها علينا فنعمل بها؟","30:13":"ولا هي في ما وراء البحر حتى تتساءلوا: من يعبر البحر لأجلنا ويأتينا بها ويتلوها علينا فنعمل بها؟","30:14":"بل الكلمة قريبة منكم جدا، في أفواهكم وقلوبكم لتعملوا بها.","30:15":"انظروا: ها أنا قد وضعت أمامكم اليوم الحياة والخير، والموت والشر،","30:16":"إذ إنني قد أوصيتكم اليوم أن تحبوا الرب إلهكم وأن تسلكوا في طرقه وتطيعوا وصاياه وفرائضه وأحكامه لتحيوا وتنموا، فيبارككم الرب في الأرض التي أنتم ماضون إليها لامتلاكها.","30:17":"ولكن إن تحولت قلوبكم ولم تطيعوا، بل غويتم وسجدتم لآلهة أخرى وعبدتموها","30:18":"فإني أنذركم اليوم أنكم لا محالة هالكون. لا تطيل الأيام على الأرض التي أنت عابر الأردن لتدخلها وتمتلكها.","30:19":"ها أنا أشهد عليكم اليوم السماء والأرض. قد وضعت أمامكم الحياة والموت، البركة واللعنة. فاختاروا الحياة لتحيوا أنتم ونسلكم،","30:20":"إذ تحبون الرب إلهكم وتطيعون صوته وتتمسكون به، لأنه هو حياتكم، وهو الذي يطيل أيامكم لتستوطنوا الأرض التي حلف الرب أن يعطيها لآبائكم إبراهيم وإسحق ويعقوب».","31:1":"ومضى موسى يقول لبني إسرائيل:","31:2":"«أنا اليوم قد بلغت من العمر مئة وعشرين سنة، وصرت عاجزا عن قيادتكم. وقد قال الرب لي: لن تعبر هذا الأردن.","31:3":"ولكن الرب إلهكم عابر أمامكم، وهو يبيد تلك الأمم من قدامكم فترثونهم. وسيكون يشوع قائدكم كما وعد الرب.","31:4":"سيصنع الرب بهم كما صنع بسيحون وعوج ملكي الأموريين وبأرضهما وأبادهما.","31:5":"فمتى أخضعهم الرب لكم فافعلوا بهم بموجب جميع الوصايا التي أمرتكم بها.","31:6":"تقووا وتشجعوا. لا تخشوهم ولا تجزعوا منهم، لأن الرب إلهكم سائر معكم، لا يهملكم ولا يترككم».","31:7":"فاستدعى موسى يشوع وقال له أمام جميع إسرائيل: «تقو وتشجع، لأنك أنت ماض مع هذا الشعب إلى الأرض التي حلف الرب لآبائهم أن يهبها لهم، وأنت توزعها عليهم.","31:8":"هوذا الرب يتقدمك، هو يكون معك، لا يهملك ولا يتركك. لذلك لا تخف ولا ترتعب».","31:9":"وكتب موسى كلمات هذه التوراة وسلمها للكهنة بني لاوي حاملي تابوت عهد الرب وإلى سائر شيوخ بني إسرائيل.","31:10":"وأمرهم موسى قائلا: «في ختام السبع السنوات، في ميعاد سنة الإبراء من الديون، في عيد المظال","31:11":"عندما يجتمع جميع الإسرائيليين للعبادة أمام الرب إلهكم في الموضع الذي يختاره، تتلون نصوص هذه التوراة في مسامعهم.","31:12":"اجمعوا الشعب رجالا ونساء وأطفالا، والغرباء المقيمين في مدنكم ليسمعوا ويتعلموا تقوى الرب إلهكم، ويحرصوا على العمل بجميع نصوص هذه التوراة.","31:13":"وكذلك ليسمع أولادهم الشريعة التي لم يعرفوها، ليتعلموا تقوى الرب إلهكم طوال الأيام التي يعيشونها على الأرض التي أنتم عابرون نهر الأردن إليها لترثوها».","31:14":"وكان الرب قد قال لموسى: «ها أنت قد أوشكت على الموت، وأيام حياتك باتت معدودة. فادع يشوع، وقفا كلاكما عند خيمة الاجتماع لكي أوصيه». فمضى موسى ويشوع ومثلا عند خيمة الاجتماع.","31:15":"فتجلى الرب في الخيمة، في سحابة. ووقفت السحابة عند باب الخيمة.","31:16":"وقال الرب لموسى: «ما إن تموت وتلحق بآبائك حتى يسرع هذا الشعب ويفجر وراء آلهة الغرباء المقيمين في الأرض التي هو داخل إليها في وسطهم، ويتخلى عني وينكث عهدي الذي أبرمته معه،","31:17":"فيحتدم غضبي عليه في ذلك اليوم، وأنبذه وأحجب وجهي عنه، فيكون فريسة. وتلحق به شرور كثيرة ومصائب، حتى يقول: أليس لأن إلهي قد هجرني، قد أصابتني هذه الشرور؟","31:18":"وأحجب وجهي عنهم من أجل جميع ما ارتكبوه من شرور، إذ سعوا وراء آلهة أخرى.","31:19":"فالآن دونوا لأنفسكم هذا النشيد وعلموه لبني إسرائيل. ضعوه في أفواههم ليكون هذا النشيد شهادة عليهم.","31:20":"لأني حالما أدخلهم إلى الأرض التي تفيض لبنا وعسلا، هذه الأرض التي حلفت أن تكون لآبائهم، فيأكلون ويشبعون ويسمنون، فإنهم يسعون وراء آلهة أخرى ويعبدونها ويزدرون بي ناقضين عهدي.","31:21":"فمتى حلت بهم شرور كثيرة ومصائب جمة، يشهد هذا النشيد عليهم، لأنه سيظل يتردد على أفواه ذريتهم، إذ إنني عالم بخواطرهم التي تدور بخلدهم الآن قبل أن أدخلهم إلى الأرض كما حلفت».","31:22":"فكتب موسى هذا النشيد في ذلك اليوم، وعلمه لبني إسرائيل.","31:23":"وأوصى الرب يشوع بن نون قائلا: «تقو وتشجع، لأنك أنت تدخل بني إسرائيل إلى الأرض التي أقسمت لهم عليها، وأنا أكون معك».","31:24":"وعندما أتم موسى تدوين نصوص هذه التوراة كاملة في كتاب،","31:25":"أمر اللاويين حاملي تابوت عهد الرب قائلا:","31:26":"«خذوا كتاب التوراة هذا وضعوه إلى جوار تابوت عهد الرب إلهكم، ليكون هناك شاهدا عليكم،","31:27":"لأني أعرف تمردكم وقساوة قلوبكم. إذ وأنا مازلت حيا معكم اليوم أخذتم في مقاومة الرب. فكم بالأحرى تتمردون بعد موتي؟","31:28":"اجمعوا إلي جميع شيوخ أسباطكم وعرفاءكم، لأتلو على مسامعهم هذه الكلمات، وأشهد عليهم السماء والأرض.","31:29":"لأنني واثق أنكم بعد موتي تفسدون وتضلون عن الطريق التي أوصيتكم بها، فيصيبكم الشر في آخر الأيام، لأنكم تقترفون الشر أمام الرب حتى تثيروا غيظه بما تجنيه أيديكم».","31:30":"فتلا موسى في مسامع كل جماعة إسرائيل كل كلمات أبيات هذا النشيد.","32:1":"«أصغي أيتها السماوات فأتكلم ولتنصت الأرض إلى أقوال فمي.","32:2":"لينهمر تعليمي كالمطر، وليقطر كلامي، فيكون كالطل على الكلإ وكالغيث على العشب.","32:3":"باسم الرب أدعو، فمجدوا عظمة إلهنا.","32:4":"هو الصخر، وصنائعه كلها كاملة، سبله جميعها عدل. هو إله أمانة لا يرتكب جورا، صديق وعادل هو.","32:5":"لقد اقترفوا الفساد أمامه، ولم يعودوا له أبناء بل لطخة عار، إنهم جيل أعوج وملتو","32:6":"أبهذا تكافئون الرب أيها الشعب الأحمق الغبي؟ أليس هو أباكم وخالقكم الذي عملكم وكونكم؟","32:7":"اذكروا الأيام الغابرة، وتأملوا في سنوات الأجيال الماضية. اسألوا آباءكم فينبئوكم، وشيوخكم فيخبروكم.","32:8":"عندما قسم العلي الميراث على الأمم، وحين فرق بني آدم، أقام حدودا للشعوب على عدد بني إسرائيل،","32:9":"لأن نصيب الرب هو شعبه، وأبناء يعقوب قرعة ميراثه.","32:10":"وجدهم في أرض قفر وفي خلاء موحش. فأحاط بهم ورعاهم وصانهم كحدقة عينه.","32:11":"وكما يهز النسر عشه، ويرف على فراخه، باسطا جناحيه ليأخذها ويحملها على منكبيه،","32:12":"هكذا الرب وحده قاد شعبه، وليس معه إله غريب.","32:13":"أصعدهم على هضاب الأرض فأكلوا ثمار الصحراء، وغذاهم بعسل من صخر، وزيت من حجر الصوان،","32:14":"وزبدة البقر ولبن الغنم وشحم خراف وتيوس وخيار كباش باشان، وأفضل لب الحنطة، وسقاهم دم العنب القاني.","32:15":"فسمن بنو إسرائيل ورفسوا، سمنوا وغلظوا واكتسوا شحما، فرفضوا الإله صانعهم وتنكروا لصخرة خلاصهم.","32:16":"أثاروا غيرته بآلهتهم الغريبة، وأغاظوه بأصنامهم الرجسة.","32:17":"قدموا محرقات لأوثان ليست هي الله، لآلهة غريبة لم يعرفوها بل ظهرت حديثا، آلهة لم يرهبها آباؤهم من قبل.","32:18":"لقد نبذتم الصخر الذي أنجبكم، ونسيتم الله الذي أنشأكم.","32:19":"فرأى الرب ذلك ورذلهم، إذ أثار أبناؤه وبناته غيظه.","32:20":"وقال: سأحجب وجهي عنهم، فأرى ماذا يكون مصيرهم؟ إنهم جيل متقلب وأولاد خونة،","32:21":"هيجوا غيرتي بعبادة أوثانهم، وأسخطوني بأصنامهم الباطلة. لذلك سأثير غيرتهم بشعب متوحش، وأغيظهم بأمة حمقاء.","32:22":"فها قد أضرم غضبي نارا تحرق حتى الهاوية السفلى، وتأكل الأرض وغلاتها، وتشعل أسس الجبال.","32:23":"أكوم عليهم شرورا وأنفذ سهامي فيهم.","32:24":"وحين يكونون خائرين من الجوع، منهوكين من الحمى والداء السام، أجعل أنياب الوحوش مع سم زواحف الأرض تنشب فيهم.","32:25":"يثكلهم سيف العدو في الطريق، ويستولي عليهم الرعب داخل الخدور، فيهلك الفتى مع الفتاة، والرضيع مع الشيخ.","32:26":"قلت: أشتتهم في زوايا الأرض، وأمحو من بين الناس ذكرهم.","32:27":"لولا خوفي من تبجح العدو، إذ يظنون قائلين: إن يدنا قد عظمت، وليس ما جرى هو من فعل الرب.","32:28":"إن بني إسرائيل أمة غبية لا بصيرة فيها.","32:29":"لو عقلوا لفطنوا لمآلهم وتأملوا في مصيرهم،","32:30":"إذ كيف يدحر واحد ألفا، ويهزم اثنان من أعدائهم عشرة آلاف منهم، لولا أن صخرهم قد هجرهم والرب قد سلمهم؟","32:31":"لأن ليس صخرهم كصخرنا، وهذا ما يقر به أعداؤنا.","32:32":"إذ إن كرمتهم هي من كرمة سدوم ومن حقول عمورة. وعنبهم ينضح سما، وعناقيدهم تفيض مرارة.","32:33":"خمرهم حمة الأفاعي وسم الثعابين المميت.","32:34":"أليس هذا مدخرا عندي مختوما عليه في خزائني؟","32:35":"لي النقمة وأنا أجازي. وفي الوقت المعين تزل أقدامهم فيوم هلاكهم بات وشيكا، ومصيرهم المحتوم يسرع إليهم،","32:36":"لأن الرب يدين شعبه ويرأف بعبيده. عندما يرى أن قوتهم قد اضمحلت ولم يبق عبد ولا حر،","32:37":"عندئذ يسأل الرب: أين آلهتهم؟ أين الصخرة التي التجأوا إليها؟","32:38":"التي كانت تلتهم شحم ذبائحهم وتشرب خمر سكائبهم؟ لتهب لمساعدتهم وتبسط عليهم حمايتها.","32:39":"انظروا الآن: إني أنا هو وليس إله آخر معي. أنا أميت وأحيي، أسحق وأشفي، ولا منقذ من يدي.","32:40":"أبسط يدي نحو السماء قائلا: حي أنا إلى الأبد.","32:41":"إذا سننت سيفي البارق وأمسكت به يدي للقضاء، فإني أنتقم من أعدائي، وأجازي مبغضي.","32:42":"أسكر سهامي بالدم ويلتهم سيفي لحما، من دم القتلى والسبايا ورؤوس قادة العدو.","32:43":"تهللي أيتها الأمم مع شعبه، لأنه سينتقم لدماء عبيده ويثأر من أعدائه ويصفح عن أرضه وعن شعبه».","32:44":"وأقبل موسى ويشوع بن نون وقرآ كلمات هذا النشيد جميعها في مسامع الشعب.","32:45":"وعندما انتهى موسى من تلاوة جميع كلمات أبيات هذا النشيد على الإسرائيليين،","32:46":"قال لهم: «تأملوا بقلوبكم في جميع هذه الكلمات التي أنا أشهد عليكم بها اليوم، لكي توصوا بها أولادكم، ليحرصوا على العمل بكلمات هذه التوراة كلها.","32:47":"لأنها ليست كلمات لا جدوى لكم منها. إنها حياتكم وبها تعيشون طويلا في الأرض التي أنتم عابرون نهر الأردن إليها لترثوها».","32:48":"وقال الرب لموسى في نفس ذلك اليوم:","32:49":"«اصعد إلى سلسلة جبال عباريم حيث جبل نبو الذي في أرض موآب مقابل أريحا، وشاهد أرض كنعان التي أنا واهبها ملكا لبني إسرائيل.","32:50":"ومت في الجبل الذي تصعد إليه، والحق بقومك كما مات أخوك هرون في جبل هور ولحق بقومه.","32:51":"لأنكما لم تثقا بي في حضور الإسرائيليين عند ماء مريبة قادش في برية صين، إذ لم تقدساني بين الشعب.","32:52":"لهذا فإنك تشهد الأرض عن بعد، ولكنك لن تدخل إلى الأرض التي أهبها لبني إسرائيل».","33:1":"وهذه هي البركة التي بارك بها موسى، رجل الله، بني إسرائيل قبل موته،","33:2":"فقال: «أقبل الرب من سيناء، وأشرف عليهم من سعير، وتألق في جبل فاران؛ جاء محاطا بعشرات الألوف من الملائكة وعن يمينه يومض برق عليهم.","33:3":"حقا إنك أنت الذي أحببت الشعب؛ وجميع القديسين في يدك، ساجدون عند قدميك يتلقون منك أقوالك،","33:4":"التي تشتمل عليها الشريعة التي أوصانا بها موسى، لتكون ميراثا لجماعة يعقوب.","33:5":"صار الرب ملكا لشعبه حين اجتمع رؤساء أسباط إسرائيل معا.","33:6":"ليحي رأوبين ولا يمت، وليتكاثر رجاله».","33:7":"وقال عن يهوذا: «اسمع يارب دعاء يهوذا، واجمع شمله بقومه، فإنه بيديه يدافع عن قضيته فأعنه على أعدائه».","33:8":"وقال عن سبط لاوي: «لقد أعطيت يارب تميمك وأوريمك لرجلك الذي جربته وامتحنته في مسة، وخاصمته عند ماء مريبة.","33:9":"الذي قال عن والديه: لم أرهما، وبإخوته لم يعترف، وأنكر أبناءه، بل أطاعوا وصاياك وصانوا عهدك.","33:10":"هم يعلمون يعقوب أحكامك وبني إسرائيل شريعتك، يحرقون بخورا أمام أنفك وقرابين على مذبحك","33:11":"بارك يارب مهاراتهم واغتبط بعمل أيديهم. حطم متون مقاوميهم ومبغضيهم فلا تقوم لهم قائمة».","33:12":"وقال عن سبط بنيامين: «إنه حبيب الرب، يسكن لديه آمنا، يصونه طول النهار، وبين منكبيه يسكن مطمئنا».","33:13":"وقال عن سبط يوسف: «ليبارك الرب أرضه بنفائس قطرات ندى السماء، وبلجج المياه الغائرة من تحت،","33:14":"وبخير ما تنميه الشمس وما تغله الأقمار،","33:15":"وبأنفس ما تدخره الجبال القديمة، وبأثمن كنوز التلال الأبدية،","33:16":"وبأفضل خيرات الأرض وبركاتها، وبرضى الساكن في العليقة. فلتنسكب هذه جميعها على رأس يوسف، على جبين الأمير بين إخوته.","33:17":"فهو في جلاله كالثور البكر، وقرناه مثل قرني ثور وحشي، ينطح بهما الشعوب، حتى أولئك المقيمين في أقاصي الأرض. لتكن هكذا عشرات ألوف أفرايم، لتكن هكذا ألوف منسى».","33:18":"وقال عن سبطي زبولون ويساكر: «افرح يازبولون بخروجك، وأنت يايساكر بخيامك،","33:19":"فإنهما يدعوان الشعب إلى الجبل حيث يقربان محرقات البر، لأنهما يشبعان من خيرات البحار، ومن الذخائر الكامنة في الرمل».","33:20":"وقال عن سبط جاد: «لتحل البركة على من وسع تخوم جاد حيث يربض جاد هناك كالأسد، يفترس الذراع مع قمة الرأس.","33:21":"اختار خير الأرض لنفسه، واحتفظ لنفسه بنصيب القائد: وعندما اجتمع شيوخ الشعب أجرى حق الرب العادل وأحكامه مع إسرائيل».","33:22":"وقال عن سبط دان: «دان مثل شبل أسد ينقض من باشان».","33:23":"وقال عن سبط نفتالي: «اشبع يانفتالي رضى، وامتليء بركة من الرب، واملك ساحل البحر الأبيض المتوسط والنقب».","33:24":"وقال عن سبط أشير: «أشير الابن الأكثر مباركة. فليكن صاحب حظوة عند إخوته، وليغمس في الزيت قدميه.","33:25":"ولتكن مزاليج أبوابك من حديد ونحاس، ولتعادل قوتك امتداد أيامك.","33:26":"ليس نظير الرب يابني إسرائيل يمتطي السماء لمعونتكم والغمام في عظمته،","33:27":"فالإله الأبدي هو ملجأكم، وتحتكم تنبسط الأذرع الأبدية، يطرد أمامكم أعداءكم قائلا: أهلكوهم.","33:28":"ليسكن بنو إسرائيل آمنين وحدهم، ولتجر ينابيع ماء يعقوب إلى أرض حنطة وخمر، وتقطر سماؤه بالندى.","33:29":"طوباكم يابني إسرائيل، أي شعب مثلكم منتصر بالرب؟ إنه ترسكم وعونكم وسيفكم المجيد. لكم يخضع أعداؤكم، وأنتم تطأون مرتفعاتهم».","34:1":"وارتقى موسى جبل نبو إلى قمة الفسجة من سهول موآب المقابلة لأريحا، فأراه الرب جميع الأرض من جلعاد إلى دان،","34:2":"وأيضا أراضي نفتالي وأفرايم ومنسى وسائر أرض يهوذا الممتدة إلى البحر الأبيض المتوسط غربا.","34:3":"وكذلك النقب في الجنوب، ووادي نهر الأردن، وأريحا مدينة النخيل حتى صوغر.","34:4":"وقال له الرب: «هذه هي الأرض التي أقسمت لإبراهيم وإسحق ويعقوب أنني سأهبها لذريتهم. قد جعلتك تراها بعينيك ولكنك إليها لن تعبر».","34:5":"فمات موسى عبد الرب في أرض موآب بموجب قول الرب.","34:6":"ودفنه في الوادي في أرض موآب، مقابل بيت فغور. ولم يعرف أحد قبره إلى هذا اليوم.","34:7":"وكان موسى قد بلغ من العمر مئة وعشرين سنة حين مات، لم يكل بصره ولا غاضت نضارته.","34:8":"وناح بنو إسرائيل على موسى في سهول موآب طوال ثلاثين يوما.","34:9":"وكان يشوع بن نون قد امتلأ روح حكمة بعد أن وضع موسى يديه عليه، فأطاعه بنو إسرائيل وعملوا بمقتضى ما أوصى به الرب موسى.","34:10":"ولم يظهر بعد نبي في بني إسرائيل مثل موسى، الذي خاطبه الرب وجها لوجه","34:11":"وأقامه ليجري جميع الآيات والمعجزات فى ديار مصر، على فرعون وعلى جميع عبيده.","34:12":"إذ لم يستطع أحد أن يصنع العظائم المخيفة بقدرة فائقة كما فعل موسى أمام كل بني إسرائيل."};
